'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='word-choice')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('rehabilitation','From re- + habilitate, from Latin habilis “fit, able”; rehabilitation is restoring health, skills, or social functioning after injury, illness, or a setback.',[C('rehabilitation.s1','通用','The patient began rehabilitation to walk safely after the hip operation.','髋部手术后，患者开始康复治疗，以便安全行走。','physical/speech rehabilitation','名词：帮助患者恢复身体或语言能力的治疗。','therapy rebuilds mobility.','医学'),C('rehabilitation.s2','通用','The program supports the rehabilitation of prisoners through education and job training.','该项目通过教育和职业培训帮助囚犯改造并重返社会。','prisoner/addiction rehabilitation','也指帮助囚犯或成瘾者恢复正常社会生活。','training supports return to community.','社会')],M('The patient’s rehabilitation made walking harder and prevented any improvement after surgery.','The patient’s rehabilitation helped restore strength and walking ability after surgery.','康复旨在恢复能力；阻碍一切改善与 rehabilitation 的目标相反。','meaning'),[Q(1,'A patient enters rehabilitation after surgery to…','recover strength or abilities','receive a property rebate','rehearse a play','Rehabilitation sense 1 is care intended to restore function.','meaning'),Q(2,'Prisoner rehabilitation may include…','education and job training for return to society','a sentence of permanent isolation only','a theatrical dress rehearsal','The second sense concerns helping people live normally after release.','context'),Q(1,'Which phrase is natural?','speech rehabilitation','rehabilitation a bridge down','rehabilitation to four quarts','Rehabilitation can modify a type of treatment such as speech therapy.','collocation'),Q(1,'Which is the central goal of rehabilitation?','restoring health or social functioning','making a condition permanently worse','replacing all medical care with punishment','The word centers on restoring capacity after harm or difficulty.','meaning')]);
P('rehash','From re- + hash, with hash in the sense “chop or work over”; rehash means present old ideas again in slightly altered form, or the recycled material itself.',[C('rehash.s1','媒体','The columnist rehashed last year’s argument without adding new evidence.','专栏作者把去年的论点重新包装了一遍，却没有补充新证据。','rehash an argument/story','动词：把旧观点稍作改动后再次提出。','same argument is reused.','媒体'),C('rehash.s2','媒体','The sequel felt like a rehash of the first film’s plot.','这部续集像是第一部电影情节的翻版。','a rehash of + old material','名词：看似新鲜、实则沿用旧内容的作品或材料。','plot repeats old material.','媒体')],M('The article was a rehash because every idea and example was completely new and had never appeared before.','The article was original because every idea and example was new.','全新材料不是旧内容的稍作改写；原句给出的理由与 rehash 相矛盾。','meaning'),[Q(1,'A writer rehashes an old argument by…','presenting the same ideas again with minor changes','testing a chemical reagent','withdrawing the argument formally','Rehash as a verb means reuse old material in a slightly altered form.','meaning'),Q(2,'A movie described as a rehash is…','a recycled version of earlier material','a first-ever story with no resemblance to past films','a movie theater’s receptionist','The noun sense labels something based on previously used content.','context'),Q(1,'Which phrase is natural?','rehash an old debate','rehash a quart of water','rehash the debate into a receptor','Rehash commonly takes an argument, story, or debate as its object.','collocation'),Q(1,'Why might a reviewer call a sequel a rehash?','it repeats the original plot with little new material','it is the first film ever made','it has no connection to the earlier film','The term criticizes recycled ideas presented as new.','meaning')]);
P('rehearsal','From Old French rehercier “go over again”; rehearsal is a practice session preparing performers for a real performance or ceremony.',C('rehearsal.s1','艺术','The orchestra held one final rehearsal before opening night.','首演之夜前，管弦乐团举行了最后一次排练。','hold/attend a rehearsal','名词：为正式演出或仪式做准备的试演或练习。','musicians practice before public event.','艺术'),M('The orchestra skipped every practice session but called its first public concert a rehearsal.','The orchestra held a rehearsal before its first public concert.','正式面对观众的首场音乐会是演出，不是排练。','distinction'),[Q(1,'A dress rehearsal is held to…','practice the performance under conditions like the real event','announce the final ticket receipts','rebuild the theater','A rehearsal prepares performers before the actual performance.','meaning'),Q(1,'Which verb commonly combines with rehearsal?','hold','recede','reclaim','A group can hold, schedule, or attend a rehearsal.','collocation'),Q(1,'The cast meets without an audience to run through the play. This is…','a rehearsal','a rebuff','a recession','Actors practice scenes during rehearsal.','context'),Q(1,'Which sentence uses rehearsal correctly?','The choir’s rehearsal lasted two hours.','The choir rehearsaled the two-hour.','The rehearsal was a realtor.','Rehearsal is a noun naming the practice session.','grammar')]);
P('rehearse','From Old French rehercier “go over again”; rehearse means practice a performance or mentally/verbally go through what one plans to say.',[C('rehearse.s1','艺术','The actors rehearsed the final scene until every cue was clear.','演员们反复排练最后一幕，直到每个提示都清楚为止。','rehearse a play/scene/performance','动词：正式演出前练习戏剧、音乐或节目。','actors repeat scene in practice.','艺术'),C('rehearse.s2','通用','She rehearsed her answer in her mind before meeting the interview panel.','见面试小组前，她在心里默述了一遍自己的回答。','rehearse what/how to say','预先默述或演练准备公开说的话。','speaker mentally practices response.','通用')],M('The actor rehearsed the scene by refusing to practice it before opening night.','The actor rehearsed the scene several times before opening night.','拒绝练习不是 rehearsal；该动词表示演出前反复排演。','meaning'),[Q(1,'Actors rehearse a scene so they can…','practice it before performing for an audience','reimburse the director','rebuild the stage after the show','Rehearse sense 1 means practice a performance.','meaning'),Q(2,'To rehearse an answer mentally is to…','think through what one plans to say','read the answer as a receipt','reject the interview panel','The second sense is to plan or say something through before speaking publicly.','context'),Q(1,'Which construction is correct?','rehearse a speech','rehearse to a speech it','rehearsal a speech out','Rehearse takes the performance or speech as its direct object.','grammar'),Q(1,'A musician runs the difficult passage repeatedly before the concert. The musician…','rehearses it','reinstates it','reclaims it','Repeated practice before performance is rehearsal.','meaning')]);
P('reheat','From re- “again” + heat, from Old English hǣtu “heat”; reheat means heat cooked food or another thing again after it has cooled.',C('reheat.s1','生活','Reheat the soup gently on the stove before serving it.','上桌前把汤放在炉子上重新加热。','reheat food in/on + appliance','及物动词：再次使已冷却的食物或物品变热。','soup is warmed again.','生活'),M('She reheated the cold soup by placing it in the refrigerator until it became colder.','She reheated the cold soup on the stove until it was hot.','冷藏会使汤更冷，而不是重新加热。','meaning'),[Q(1,'To reheat leftovers is to…','warm them again after they have cooled','freeze them permanently','serve them for the first time without warming','Reheat means heat something once more.','meaning'),Q(1,'Which phrase is natural?','reheat the rice in a microwave','reheat the receipt at reception','reheat the soup into a quart','Food can be reheated in an appliance such as a microwave.','collocation'),Q(1,'A cook warms yesterday’s casserole before dinner. The cook…','reheats it','rehearses it','rehydrates it','The food has already been cooked and is being heated again.','context'),Q(1,'What does re- mean in reheat?','again','below','without','Re- marks a repeated action.','word-formation')]);
P('rehydrate','From re- + hydrate, based on Greek hydōr “water”; rehydrate means restore water to a dehydrated person or substance.',C('rehydrate.s1','医学','After the long race, the medic helped the runner rehydrate with water and electrolytes.','长跑结束后，医护人员帮助跑者补充水分和电解质。','rehydrate a person/body; rehydrate dried food','及物或不及物用法：补回流失的水分，也可使干燥物吸水。','fluids replace what was lost.','医学'),M('The dehydrated runner rehydrated by avoiding all liquids in the heat.','The dehydrated runner rehydrated by drinking water and an electrolyte solution.','避免液体会加重脱水，不会补回水分。','meaning'),[Q(1,'A person who rehydrates after exercise…','replaces fluids lost through sweating','removes all water from the body','reapplies for a race','Rehydrate means restore water to a dehydrated body.','meaning'),Q(1,'Dried mushrooms can be rehydrated by…','soaking them in water','baking them until drier','putting them in a rehearsal room','Dry food can absorb water again.','context'),Q(1,'Which phrase is natural?','rehydrate after a long run','rehydrate the run into a receipt','rehydrate with no fluids at all','One can rehydrate after losing fluid through exercise or heat.','collocation'),Q(1,'The prefix re- in rehydrate means…','again or back','not','underneath','Rehydration puts water back into something that has dried out.','word-formation')]);
P('reign','From Old French regner, from Latin regnare “rule”; reign can mean a monarch’s period in power, to rule, or to be the dominant influence.',[C('reign.s1','历史','The king’s reign lasted forty years and included a long period of peace.','这位国王的统治持续了四十年，其间有一段长期和平时期。','during/throughout + reign','名词：君主在位或统治的时期。','period is measured in years.','历史'),C('reign.s2','政治','Queen Isabella reigned over the island kingdom for three decades.','伊莎贝拉女王统治这个岛国三十年。','reign over + country/people','动词：作为君主统治国家或人民。','queen holds sovereign power.','政治'),C('reign.s3','书面','For years, fear reigned in the abandoned district after dark.','多年间，天黑后恐惧笼罩着那片废弃街区。','peace/fear/confusion reigns','引申为某种影响或气氛占据主导地位。','fear is strongest influence.','书面')],M('The queen’s reign ended the day before she first took the throne.','The queen’s reign began when she took the throne.','君主的 reign 是其在位时期，不可能在登基前结束。','meaning'),[Q(1,'A king’s reign is…','the period during which he rules','a receipt for the royal crown','the practice before a concert','Reign as a noun refers to a monarch’s time in power.','meaning'),Q(2,'To reign over a country is to…','rule it as a monarch','reapply for citizenship','reheat its food','Reign as a verb means govern as king or queen.','meaning'),Q(3,'“Confusion reigned in the room” means…','confusion was the dominant condition','a king entered the room','the room was rehearsing','The figurative sense describes a powerful prevailing influence.','context'),Q(1,'Which phrase is correct?','reign over the kingdom','reign the kingdom for','reign to the kingdom at','Reign over is the common construction for the country ruled.','grammar')]);
P('reigning','From reign + -ing; reign derives from Latin regnare “rule.” Reigning means currently ruling or currently holding a title/championship.',C('reigning.s1','通用','The reigning champion returned to defend her title this season.','现任冠军本赛季回来卫冕。','the reigning champion/monarch','形容词：目前在位或持有冠军头衔。','athlete currently holds title.','体育'),M('The reigning champion had lost the title years ago and no longer held it.','The former champion had lost the title years ago and no longer held it.','已失去头衔多年的人是 former champion，不是 reigning champion。','meaning'),[Q(1,'A reigning monarch is…','the monarch currently ruling','a monarch from the distant past only','a person rehearsing for a play','Reigning indicates that the person rules now.','meaning'),Q(1,'A reigning champion is the person who…','currently holds the championship title','has never competed','received a real-estate rebate','The reigning champion is the current title holder.','context'),Q(1,'Which phrase is natural?','the reigning world champion','the reigning of the champion','the champion reigningly','Reigning commonly modifies champion or monarch.','collocation'),Q(1,'Which word contrasts with reigning champion?','former champion','current champion','title holder','Former indicates the person no longer holds the title.','distinction')]);
P('reimburse','From French rembourser, from re- “back” + bourse “purse”; reimburse means pay back money someone spent on an authorized expense.',C('reimburse.s1','商务','The company will reimburse employees for approved travel costs.','公司会报销员工获批的差旅费用。','reimburse someone for + expense','动词：偿还他人先行垫付的费用。','employer returns costs paid by staff.','商务'),M('The company reimbursed her by requiring her to pay the travel costs again.','The company reimbursed her by paying back the travel costs she had advanced.','要求再付款不是偿还；reimburse 是把已支出的款项还给对方。','meaning'),[Q(1,'If an employer reimburses an employee for a taxi fare, the employer…','pays the employee back for the expense','charges the employee a second fare','rehearses the trip','Reimburse means repay money someone has spent.','meaning'),Q(1,'Which pattern is correct?','reimburse her for the ticket','reimburse the ticket to her for','reimburse at her the ticket','Reimburse someone for an expense is the standard construction.','grammar'),Q(1,'A worker submits meal receipts after a business trip to…','claim reimbursement','reclaim a quarry','reign over a hotel','Receipts document expenses that may be repaid by the employer.','context'),Q(1,'Which word is closest to reimburse?','repay','reject','rehydrate','Reimburse means pay back an expense.','meaning')]);
P('reimbursement','From reimburse + -ment; reimburse comes through French rembourser “put money back in the purse.” Reimbursement is repayment of an approved expense.',C('reimbursement.s1','商业','Submit the original receipts to request reimbursement for the conference hotel.','请提交原始收据，以申请报销会议酒店费用。','request/receive reimbursement for + cost','名词：偿还某人先前垫付的合规费用。','receipts document the hotel expense.','商业'),M('The reimbursement made the employee pay the same hotel bill twice without receiving any money back.','The reimbursement returned the hotel cost the employee had paid in advance.','报销是把已垫付的钱还给员工，而不是让其重复付款。','meaning'),[Q(1,'A reimbursement is…','money paid back for an expense','a new charge added to an account','a reigning monarch','Reimbursement is repayment of costs already paid.','meaning'),Q(1,'Which phrase is natural?','apply for reimbursement','reimbursement the hotel out','reimbursement under a queen','One applies for reimbursement for eligible expenses.','collocation'),Q(1,'Why keep receipts when seeking reimbursement?','they provide evidence of the expenses paid','they make the trip more recent','they reheat the hotel room','Receipts support a claim for repayment.','context'),Q(1,'What is the noun related to reimburse?','reimbursement','reimbursemently','reimbursedness','Reimbursement names the act or amount of repaying costs.','word-formation')]);
P('rein','From Old French rene, perhaps related to Latin retinere “hold back”; a rein is a strap for guiding a horse, and figuratively a means of control; the verb means control more strictly.',[C('rein.s1','生活','The rider shortened one rein to guide the horse around the gate.','骑手收短一侧缰绳，引导马绕过大门。','hold/tighten/pull the reins','名词：用来控制和引导马匹的长带子。','rider guides horse with leather strap.','生活'),C('rein.s2','书面','The new director took the reins of the organization in June.','新主任于六月接管了该组织。','take/hold the reins','引申为掌握组织或局势的控制权。','director assumes leadership.','书面'),C('rein.s3','通用','The editor reined in the article’s more exaggerated claims.','编辑控制了文章中过于夸张的说法。','rein in + person/behavior/claim','动词短语：约束或更严格地控制。','editor limits excess.','通用')],M('The editor reined in the claims by making them more extreme and less controlled.','The editor reined in the claims by removing exaggerations and limiting their scope.','rein in 意为约束，扩大夸张程度与之相反。','meaning'),[Q(1,'A horse’s rein is…','a strap used to guide and control it','a written receipt','a ruler’s period in office','A rein is a leather strap attached to a bridle.','meaning'),Q(2,'If someone takes the reins of a company, they…','take control or leadership','reapply for a job','reheat the company’s food','The figurative phrase means assume control.','meaning'),Q(3,'To rein in spending is to…','control or limit it','increase it without limit','return it to a store','Rein in means bring something under stricter control.','context'),Q(1,'Which phrase is idiomatic?','take the reins','take the reins in a box as a receipt','reins to rehydrate the horse','Take the reins means take charge.','collocation')]);
P('reincarnation','From re- + incarnation, from Latin caro “flesh”; reincarnation is the belief that a soul is born again in another body, or a person thought to be such a new life.',[C('reincarnation.s1','宗教','The story follows a family who believe their child is the reincarnation of an ancestor.','故事讲述一个家庭相信，他们的孩子是某位祖先的转世。','belief in reincarnation; reincarnation of + person','名词：死后灵魂转生到新身体的信仰或一次转世。','child is believed to be a soul reborn.','宗教')],M('Reincarnation means the soul ceases to exist permanently at death and is never born again.','Reincarnation is the belief that the soul may be born again in another body.','永不再生是转世观念的反面。','distinction'),[Q(1,'Reincarnation is the belief that…','a soul may be born again in a new body','a person can reheat a meal','a ruler’s reign lasts forever','The term refers to rebirth into another body after death.','meaning'),Q(1,'A character is called the reincarnation of an ancestor because…','the family believes the ancestor’s soul returned in the child','the child has received an inheritance receipt','the child is a reigning monarch','The figurative or religious use links a new life with a former person.','context'),Q(1,'Which phrase is natural?','belief in reincarnation','reincarnation at a quart','reincarnation the horse in','One can speak of a belief in reincarnation.','collocation'),Q(1,'What does re- suggest in reincarnation?','again','without','beneath','The formation refers to being embodied or born again.','word-formation')]);
P('reindeer','From Old Norse hreindyri, “reindeer animal”; a reindeer is a large northern deer, and the plural can refer collectively to a herd used for transport or food.',[C('reindeer.s1','通用','A reindeer crossed the snowy road in front of the bus.','一头驯鹿从公交车前穿过积雪覆盖的道路。','a reindeer; reindeer antlers','名词：生活在寒冷北方地区、长有宽大鹿角的大型鹿。','animal inhabits northern region.','通用'),C('reindeer.s2','通用','Reindeer have long provided northern communities with transport and food.','驯鹿长期为北方社群提供交通工具和食物。','a herd of reindeer; reindeer as a group','集合用法可指用于交通或食物来源的驯鹿群。','herd supports travel and subsistence.','通用')],M('The reindeer was a tropical fish with gills that lived in warm coral reefs.','The reindeer was a large deer adapted to cold northern lands.','驯鹿是北方鹿类，不是生活在热带珊瑚礁中的鱼。','meaning'),[Q(1,'A reindeer is a…','large deer from cold northern regions','tropical fish','chemical reagent','Reindeer are deer adapted to northern climates.','meaning'),Q(2,'A community may keep reindeer for…','transport and food','rehearsing a play','measuring temperature','Herds have traditionally supported northern travel and subsistence.','context'),Q(1,'Which phrase is natural?','a reindeer herd','a reindeer of three quarts','reindeer the door off','Reindeer can be counted as individual animals or described as a herd.','collocation'),Q(1,'Which feature is typical of a reindeer?','wide antlers','gills and fins','a bridle and reins','Reindeer are deer with antlers, unlike fish or riding equipment.','meaning')]);
P('reinforce','From re- + enforce, from Old French enforcier “strengthen,” based on Latin fortis “strong”; reinforce means strengthen an idea, send support, or make a structure stronger.',[C('reinforce.s1','通用','The teacher used a second example to reinforce the grammar rule.','老师用第二个例子进一步强化了语法规则。','reinforce an idea/message/effect','使观点、感受或效果更强。','extra example strengthens the rule.','通用'),C('reinforce.s2','军事','The commander sent two units to reinforce the northern position.','指挥官派出两个部队增援北部阵地。','reinforce troops/position','派遣额外士兵或物资提供支援。','additional units strengthen position.','军事'),C('reinforce.s3','建筑','Steel bars reinforce the concrete bridge supports.','钢筋加固了混凝土桥墩。','reinforce a wall/structure','通过添加支撑材料使实体结构更坚固。','steel strengthens physical supports.','建筑')],M('Steel bars reinforced the bridge by weakening its supports and making collapse more likely.','Steel bars reinforced the bridge by strengthening its supports.','削弱桥梁支撑与加固结构的意思相反。','meaning'),[Q(1,'A teacher reinforces a rule by…','adding examples that make it clearer and stronger','erasing every example','reheating the classroom','Reinforce sense 1 means strengthen an idea or effect.','meaning'),Q(2,'To reinforce a military position is to…','send extra troops or supplies','withdraw all support','reimburse the commander','The military sense means provide additional forces or materials.','meaning'),Q(3,'Steel bars reinforce concrete by…','making the structure physically stronger','making it more likely to collapse','changing its reign','Reinforce can strengthen a physical structure.','context'),Q(1,'Which object can be reinforced figuratively?','an argument','a receipt only','a rehearsal room only','An argument can be reinforced with supporting evidence.','collocation')]);
P('reinforced','From reinforce + past-participle suffix -ed; reinforce is based on force/fortis “strong.” Reinforced means strengthened with extra material or support.',C('reinforced.s1','工程','The workers installed reinforced panels around the glass entrance.','工人们在玻璃入口周围安装了加固面板。','reinforced concrete/material/structure','形容词：通过增加钢筋、层次或力量而加强的。','extra material adds strength.','工程'),M('The reinforced wall had no added support and collapsed more easily than before.','The reinforced wall had added supports and resisted damage better.','没有增加支撑且更易坍塌，不符合 reinforced。','meaning'),[Q(1,'Reinforced concrete contains…','extra materials such as steel that strengthen it','no support at all','a receipt inside the mixture','Reinforced means strengthened by added support.','meaning'),Q(1,'Which phrase is natural?','reinforced glass','reinforced of a receipt','reinforce glassed','Reinforced commonly modifies materials and structures.','collocation'),Q(1,'A reinforced door resists forced entry because it…','has been strengthened with extra support','has no hinges','is being rehearsed','The adjective indicates added strength.','context'),Q(1,'Which is closest to reinforced?','strengthened','weakened','receded','Reinforced means made stronger.','meaning')]);
P('reinforcement','From reinforce + -ment; reinforce combines re- with a word based on Latin fortis “strong.” Reinforcement is added strength, troops, material, or a psychological reward that encourages behavior.',[C('reinforcement.s1','通用','The bridge supports needed reinforcement before heavy vehicles could cross.','在重型车辆通行前，桥梁支撑结构需要加固。','reinforcement for/of + structure/position','名词：使某物更坚固的额外支撑；也可指增援或强化行为。','extra support improves strength.','建筑'),C('reinforcement.s1','通用','The commander requested reinforcement for the exhausted unit.','指挥官为疲惫的部队请求增援。','send/request reinforcements','名词可指额外士兵或支援力量。','additional troops are sent.','军事'),C('reinforcement.s1','通用','In training, praise can serve as positive reinforcement for safe behavior.','在训练中，表扬可以作为鼓励安全行为的正向强化。','positive/negative reinforcement','心理学中指强化某行为的奖励或结果。','praise encourages repeated behavior.','心理')],M('The bridge received reinforcement when workers removed its supports and added no material.','The bridge received reinforcement when workers added steel supports.','移除支撑而不增加材料会削弱结构，不是加固。','meaning'),[Q(1,'Structural reinforcement is…','added support that makes something stronger','a reason to delay a meeting','a reindeer herd','Reinforcement can be additional strength or support.','meaning'),Q(1,'Military reinforcements are…','extra troops or supplies sent to help','the troops who have surrendered','a bridge’s steel bars only','The word can name additional forces sent to support a position.','meaning'),Q(1,'Positive reinforcement in training may be…','praise that encourages a behavior to happen again','a punishment that discourages it','a rehearsal of an unrelated play','Positive reinforcement rewards behavior to increase its recurrence.','context'),Q(1,'Which phrase is natural?','request reinforcement for the unit','reinforcement the unit out','reimbursement for reinforcemently','One can request reinforcements for a unit or position.','collocation')]);
P('reinstate','From re- + instate, based on Latin status “standing, position”; reinstate means put someone or something back in a former job, position, or condition.',C('reinstate.s1','职业','The board voted to reinstate the teacher after reviewing the evidence.','董事会审查证据后投票决定恢复这名教师的职位。','reinstate someone in/to + position','恢复某人原有职位、身份或原先状态。','teacher returns to previous job.','职业'),M('The board reinstated the employee by permanently dismissing her and refusing to restore her post.','The board reinstated the employee by returning her to her former post.','永久解雇且不恢复职位是 dismiss，不是 reinstate。','meaning'),[Q(1,'To reinstate a dismissed employee is to…','restore the person to the former job','dismiss the person a second time','send a reindeer to the office','Reinstate means put someone back in a previous position.','meaning'),Q(1,'Which phrase is natural?','reinstate her as director','reinstate her of director to','reinstate the director into a receipt','One can reinstate someone as a former office-holder.','grammar'),Q(1,'A court reinstates a license. The license is…','restored after it had been withdrawn','reinterpreted as a novel','reheated after cooling','Reinstate can restore a status or right.','context'),Q(1,'What does re- mean in reinstate?','again or back','not','under','The verb returns someone or something to an earlier state.','word-formation')]);
P('reinterpret','From re- + interpret, from Latin interpretari “explain”; reinterpret means explain or understand a text, event, or work in a new way.',C('reinterpret.s1','学术','The historian reinterpreted the letter after finding a newly dated archive.','发现一份日期更新的档案后，历史学家对这封信作了重新解释。','reinterpret a text/event/data','重新说明或理解某事物的意义。','new evidence changes reading.','学术'),M('The historian reinterpreted the letter by repeating the exact same explanation without considering new evidence.','The historian repeated the earlier interpretation instead of reinterpreting the letter.','不改变理解且不提出新解释不是 reinterpret。','meaning'),[Q(1,'To reinterpret a poem is to…','offer a new explanation of its meaning','repeat it aloud without thought','reheat it before reading','Reinterpret means give a text or event a new reading.','meaning'),Q(1,'Which phrase is natural?','reinterpret the evidence','reinterpret the evidence into a receipt','reinterpret for the archive it','The verb takes the text, event, or data being understood anew.','grammar'),Q(1,'New historical documents lead a scholar to reinterpret a speech. The scholar…','revises the speech’s meaning in light of new evidence','reinstates the speaker','reimburses the archive','Reinterpretation can follow the discovery of new evidence.','context'),Q(1,'The prefix re- in reinterpret signals…','doing the interpreting again or differently','refusing to interpret','interpreting before reading','The verb describes a new interpretation.','word-formation')]);
P('reinterpretation','From reinterpret + -ation; interpret comes from Latin interpretari. Reinterpretation is a revised explanation that replaces or changes an earlier reading.',C('reinterpretation.s1','学术','The play’s reinterpretation shifted the setting from a palace to a modern courtroom.','这部戏的新诠释把背景从宫殿改到了现代法庭。','a reinterpretation of + text/work/event','名词：取代或修订先前理解的新解释。','production changes setting and meaning.','艺术'),M('The reinterpretation changed nothing and repeated the earlier reading word for word.','The reinterpretation offered a new reading that differed from the earlier one.','完全照搬旧解释不是重新诠释。','meaning'),[Q(1,'A reinterpretation of a novel is…','a new or revised explanation of its meaning','the original text’s receipt','a rehearsal with no changes','Reinterpretation revises or replaces an earlier reading.','meaning'),Q(1,'Which phrase is natural?','a reinterpretation of the play','a reinterpretation in four quarts','reinterpretation the curtains out','Of identifies the work receiving a new interpretation.','collocation'),Q(1,'A director moves a classic story to the present day. This may be…','a reinterpretation of the story','a reimbursement','a reigning period','Changing the setting can offer a new way to understand the work.','context'),Q(1,'Which noun is formed from reinterpret?','reinterpretation','reinterpreterly','reinterpretingness','The suffix -ation forms the noun for the act or result.','word-formation')]);
P('reinvigorate','From re- + invigorate, from Latin vigor “liveliness, strength”; reinvigorate means restore energy or strength to something tired or inactive.',C('reinvigorate.s1','通用','The new coach’s training plan reinvigorated the tired team.','新教练的训练计划让疲惫的队伍重新振作起来。','reinvigorate a person/team/campaign','及物动词：给疲惫的人、组织或活动恢复活力。','fresh approach restores energy.','通用'),M('The new policy reinvigorated the campaign by exhausting volunteers and ending all activity.','The new policy reinvigorated the campaign by renewing volunteer energy and attracting support.','耗尽志愿者并终止活动会削弱而非恢复活力。','meaning'),[Q(1,'To reinvigorate a tired team is to…','give it new energy','make it more exhausted','send it a reimbursement form','Reinvigorate means restore vigor or strength.','meaning'),Q(1,'Which phrase is natural?','reinvigorate the campaign','reinvigorate the campaign into a receipt','reinvigorate at the team with','A campaign or organization can be reinvigorated by renewed energy.','collocation'),Q(1,'A new schedule brings attendance back to a declining club. It may…','reinvigorate the club','relegate the club to a quarry','rehydrate the schedule','The change renews the club’s activity.','context'),Q(1,'What does re- contribute to reinvigorate?','restore again','without','below','The verb means put vigor back into something.','word-formation')]);
P('reiterate','From re- + iterate, from Latin iterare “do again”; reiterate means say something again, usually to stress or clarify it.',[C('reiterate.s1','通用','The chair reiterated that every visitor must sign in at the front desk.','主席再次强调，每位访客都必须在前台登记。','reiterate that + clause; reiterate a point','动词：为强调或澄清而再次说。','chair repeats a rule for emphasis.','通用'),C('reiterate.s2','通用','The report reiterates the same warning on each page.','报告每一页都反复重申同一警告。','reiterate a warning/message','也可指反复做或重复表达。','warning is repeated throughout.','通用')],M('The chair reiterated the rule by announcing that it had been cancelled and must never be followed.','The chair reiterated the rule by stating it once more for emphasis.','宣布废除与再次强调原规则意思相反。','meaning'),[Q(1,'Why did the chair reiterate the sign-in rule?','to state it again for emphasis','to withdraw it without saying it again','to relegate the desk','Reiterate means say something again, often to make it clear.','meaning'),Q(2,'A report reiterates a warning throughout its pages. It…','repeats the warning','rejects the warning as invalid','counts the warning as a relative','This use describes repeated expression of the same message.','context'),Q(1,'Which construction is correct?','reiterate that visitors must sign in','reiterate visitors to signing in','reiterate of visitors sign in','Reiterate can be followed by a that-clause.','grammar'),Q(1,'Which is closest to reiterate?','repeat for emphasis','erase permanently','quietly disagree','The prefix re- and source verb suggest doing or saying again.','word-formation')]);
P('reject','From Latin reicere “throw back,” from re- + iacere “throw”; reject means refuse to accept, or decide that a person or thing is unsuitable.',[C('reject.s1','通用','The editor rejected the article because its evidence could not be verified.','编辑因证据无法核实而拒绝了这篇文章。','reject an offer/application/idea','动词：拒绝接受某个提议、申请或观点。','editor declines an article.','出版'),C('reject.s2','医学','The transplant team watched for signs that the patient might reject the new organ.','移植团队密切观察患者是否会排斥新器官。','reject a transplant/organ','医学：身体的免疫系统排斥移植器官。','immune response attacks graft.','医学'),C('reject.s3','工业','The factory separated each reject from the products that passed inspection.','工厂把每件不合格品与通过检验的产品分开。','a factory reject; reject product','名词：因不合格而被淘汰的人或产品。','defective item is sorted out.','工业')],M('The editor rejected the article by accepting it for publication without changes.','The editor accepted the article for publication without changes.','无修改地接受发表是 accept，不是 reject。','meaning'),[Q(1,'The editor rejected a submission. What happened?','the editor refused to accept it','the editor published it unchanged','the editor reimbursed the author','Reject sense 1 means refuse to accept.','meaning'),Q(2,'A transplant patient’s body may reject an organ when…','the immune system attacks the transplanted organ','the hospital schedules a rehearsal','the organ has already been accepted by the body','In medicine, reject describes an immune response against a graft.','context'),Q(3,'On a factory label, a reject is…','a product that failed inspection','a product guaranteed to pass inspection','a worker’s family relation','The noun can name an item rejected as defective.','meaning'),Q(1,'Which phrase is natural?','reject an offer','reject to an offer','reject of the offered','Reject takes the thing refused as a direct object.','grammar')]);
P('rejection','From reject + -ion, through Latin rejectionem; rejection is the act of refusing to accept something or refusing to approve it.',[C('rejection.s1','社会','She handled the rejection of her proposal calmly and asked for feedback.','她平静地接受了提案被拒，并询问反馈意见。','rejection of an offer/application','名词：拒绝接受或考虑某事。','proposal is not accepted.','社会'),C('rejection.s2','法律','The court issued a written rejection of the appeal.','法院书面驳回了上诉。','rejection of an appeal/claim','法律语境中指不予批准或驳回。','appeal is denied by court.','法律')],M('The rejection of the appeal meant that the court approved it and ordered a new trial.','The rejection of the appeal meant that the court refused to approve it.','驳回上诉表示不批准，而不是批准。','meaning'),[Q(1,'An application receives a rejection. The applicant…','was refused','was guaranteed acceptance','was appointed a relative','Rejection is refusal to accept an application.','meaning'),Q(2,'A court’s rejection of an appeal means it…','refuses to allow or approve the appeal','automatically orders a new hearing','rehearses the case publicly','The legal sense concerns denying approval.','context'),Q(1,'Which phrase is natural?','the rejection of a claim','the rejection to a claim','rejecting of claim it','Rejection commonly takes an of-phrase naming what is refused.','collocation'),Q(1,'Which verb is closest to rejection?','refusal','approval','reimbursement','Rejection describes an act of refusing.','meaning')]);
P('rejoice','From Old French rejoir, based on Latin gaudere “be glad”; rejoice means feel or show great happiness.',[C('rejoice.s1','书面','The villagers rejoiced when the river finally returned to its normal level.','河水终于恢复正常水位时，村民们欢欣不已。','rejoice at/in/over + good news','动词：感到或表现出极大的喜悦。','community celebrates good outcome.','书面'),C('rejoice.s2','旧用法','The good news rejoiced the family, though this transitive use is now uncommon.','这个好消息使那一家人欢喜，尽管这种及物用法如今少见。','rejoice someone (old use)','旧用法：使某人高兴。','news causes happiness.','旧用法')],M('The villagers rejoiced at the tragedy because it brought them only grief and no relief.','The villagers mourned the tragedy; they rejoiced at the later rescue.','悲痛并非欢欣；原句把相反情感混为一谈。','distinction'),[Q(1,'The villagers rejoiced when the river receded safely. They…','felt or showed great happiness','were angry that a festival was cancelled','asked for a reimbursement','Rejoice means feel or express great joy.','meaning'),Q(2,'In the older transitive use, “The news rejoiced her” means…','the news made her glad','she rejected the news','she was a relative of the news','This less common older use takes the person made happy as object.','context'),Q(1,'Which phrase is idiomatic?','rejoice at the good news','rejoice the good news at','rejoice of good news','Rejoice is commonly followed by at, in, or over for the cause of joy.','grammar'),Q(1,'A team wins a hard-fought final and celebrates. The players…','rejoice','recede','relegate','Their celebration expresses great happiness.','context')]);
P('rejoin','From re- + join, from Old French joindre “join”; rejoin means join a group, route, or person again.',C('rejoin.s1','通用','After collecting her coat, Lena rejoined her friends in the lobby.','取回外套后，莉娜回到大厅与朋友们会合。','rejoin a group/person/team','动词：再次加入某个群体，或重新回到同伴身边。','she returns to friends.','通用'),M('After her break, Lena rejoined the group by leaving the building and never returning.','After her break, Lena returned and rejoined the group.','离开且不再回来不符合重新加入。','meaning'),[Q(1,'Lena rejoined her friends after the break. She…','came back to them','rejected them permanently','sent them a reimbursement','Rejoin means join people again after being away.','meaning'),Q(1,'Which phrase is natural?','rejoin the team','rejoin to the team','rejoin with the team again to','Rejoin takes the group directly as its object.','grammar'),Q(1,'A passenger gets off briefly and then boards the same tour group again. The passenger…','rejoins the group','rehearses the group','relegates the group','The passenger returns to a group previously left.','context'),Q(1,'What does re- indicate in rejoin?','again','before','against','It marks joining once more.','word-formation')]);
P('rejoinder','From rejoin in the older sense “reply,” ultimately from French joindre “join”; a rejoinder is a prompt response, often a sharp reply to a remark.',C('rejoinder.s1','书面','When the critic called the plan impossible, the engineer’s rejoinder was that the bridge already existed.','评论者说计划不可能时，工程师立即反驳说桥已经建成。','a rejoinder to + remark/argument','名词：对刚才的话作出的迅速回应，常带反驳意味。','engineer answers critic promptly.','书面'),M('Her rejoinder was silence delivered weeks later in a separate report, not a reply to the remark.','Her rejoinder was an immediate, pointed answer to the remark.','rejoinder 指针对某话作出的回应，不是隔周才出现的无关沉默。','meaning'),[Q(1,'A rejoinder is usually…','a quick reply to something just said','a formal payment for travel','a second rehearsal of a play','It names a response, often a sharp one.','meaning'),Q(1,'The engineer’s rejoinder to the critic was…','a pointed answer challenging the criticism','an unrelated weather report a month later','a list of family relatives','A rejoinder directly responds to a remark or argument.','context'),Q(1,'Which phrase is natural?','a rejoinder to the accusation','a rejoinder at the accusation of','rejoinder the accusation out','To introduces the remark being answered.','grammar'),Q(1,'Which is closest to rejoinder?','retort','silence','reimbursement','A rejoinder is a reply, sometimes a retort.','meaning')]);
P('rejuvenate','From re- + Latin iuvenis “young”; rejuvenate means make someone feel or look young again, or bring new life to a place or activity.',[C('rejuvenate.s1','通用','A week away from email helped rejuvenate the exhausted project manager.','离开电子邮件休息一周，帮助筋疲力尽的项目经理恢复了活力。','rejuvenate someone/oneself','动词：使人恢复年轻感、活力或精神。','rest renews energy.','通用'),C('rejuvenate.s2','通用','The grant will rejuvenate the neglected waterfront with parks and workshops.','这笔拨款将通过修建公园和工坊让荒废的滨水区焕发新生。','rejuvenate a neighborhood/business','引申为使地方、组织或活动恢复生机。','investment brings area back to life.','城市')],M('The grant rejuvenated the waterfront by closing its parks and removing every public facility.','The grant rejuvenated the waterfront by reopening parks and adding public facilities.','关闭设施会使滨水区衰败，不是让它恢复活力。','meaning'),[Q(1,'A quiet holiday can rejuvenate an exhausted person by…','helping the person regain energy','making the person permanently more tired','reinstating an expired parking ticket','Rejuvenate sense 1 means make someone feel young or lively again.','meaning'),Q(2,'A grant may rejuvenate a neglected district by…','bringing new activity and facilities to it','closing its parks and shops','rejecting every improvement proposal','This figurative sense means bring new life to a place.','context'),Q(1,'Which phrase is natural?','rejuvenate the old town','rejuvenate to the old town','rejuvenate of the town it','Rejuvenate takes the person or place being renewed as its object.','grammar'),Q(1,'A renovation draws visitors back to a fading market. It may…','rejuvenate the market','relegate the market','reheat the market','The renovation restores activity and energy.','context')]);
P('rekindle','From re- + kindle, an old verb meaning “set fire to”; rekindle means light something again or bring back a feeling such as hope or interest.',[C('rekindle.s1','生活','She used dry twigs to rekindle the fire after the wind blew it out.','风把火吹灭后，她用干树枝重新点燃了火。','rekindle a fire/flame','动词：火熄灭后再次点燃。','fresh kindling relights fire.','生活'),C('rekindle.s2','通用','The reunion rekindled their interest in the family history project.','这次重聚重新点燃了他们对家族史项目的兴趣。','rekindle interest/hope/relationship','引申为使兴趣、希望或感情重新出现。','meeting revives interest.','通用')],M('The reunion rekindled their interest by making them permanently lose all curiosity about the project.','The reunion rekindled their interest and encouraged them to continue the project.','失去全部兴趣与重新燃起兴趣相反。','meaning'),[Q(1,'To rekindle a fire is to…','light it again after it has gone out','pour water on it until it is cold','move it to another town','The literal sense concerns lighting a fire again.','meaning'),Q(2,'The reunion rekindled their interest in the project. Their interest…','returned after having faded','was extinguished permanently','was reimbursed by the organizer','The figurative sense revives a feeling or enthusiasm.','context'),Q(1,'Which phrase is natural?','rekindle hope','rekindle at hope to','rekindle hope from of','Rekindle commonly takes a feeling such as hope or interest as its object.','collocation'),Q(1,'What does re- contribute to rekindle?','again','not','under','It indicates that the fire or feeling is brought back.','word-formation')]);
P('relapse','From Latin relabi “slip back,” from re- + labi “slip”; relapse is a return to illness or a bad habit after improvement, or to fall back into it.',[C('relapse.s1','医学','The symptoms returned after a month of improvement, and the doctor called it a relapse.','病情好转一个月后症状复发，医生称之为复发。','a relapse into/of illness','名词：康复或好转后疾病再次发作。','symptoms return after progress.','医学'),C('relapse.s2','通用','After six months without smoking, he feared a relapse into the habit.','戒烟六个月后，他担心自己会故态复萌。','a relapse into bad habits','名词：改进后重新陷入旧有不良习惯。','old habit returns.','通用'),C('relapse.s3','通用','Without support, the patient may relapse into the same harmful behavior.','如果没有支持，患者可能会重新陷入同样的有害行为。','relapse into + illness/habit','动词：重新陷入疾病或旧有不良行为。','person falls back into behavior.','通用')],M('After six months of recovery, the return of the same symptoms was called a relapse even though the patient remained completely well.','After six months of recovery, the return of the same symptoms was called a relapse.','症状重新出现正是疾病复发的情形，句中“完全康复”与事实自相矛盾。','meaning'),[Q(1,'A medical relapse occurs when…','an illness returns after improvement','a patient receives a reimbursement','a treatment is rehearsed','Relapse sense 1 is a return of illness after getting better.','meaning'),Q(2,'A relapse into an old habit is…','a return to that habit after progress','a permanent escape from it','a relative joining the household','The second sense covers a return to bad behavior.','context'),Q(3,'Which sentence uses relapse as a verb?','He may relapse into the habit without support.','The relapse of his cousin attended the meeting.','He was a relapse of the habit.','The verb pattern is relapse into an illness or behavior.','grammar'),Q(1,'Which phrase is natural?','a relapse of the disease','a relapse the disease on','a relapse at being fully cured','Relapse can name the return of a disease.','collocation')]);
P('relate','From Latin relatus, past participle of referre “carry back”; relate means connect things, be connected with something, tell a story, or identify with someone.',[C('relate.s1','通用','The analyst related the sudden cost increase to a change in shipping fees.','分析师把成本突然上涨与运费变化联系起来。','relate A to B','动词：说明或发现两个事物之间的联系。','cost rise is connected with shipping.','通用'),C('relate.s2','通用','The new safety rule relates to all visitors entering the laboratory.','这项新安全规定适用于所有进入实验室的访客。','relate to + subject/person','指与某主题有关或适用于某人某事。','rule concerns every visitor.','通用'),C('relate.s3','书面','The witness related what she had seen during the storm.','证人叙述了她在暴风雨期间看到的情况。','relate what/how + clause; relate a story','动词：讲述经历或事件。','witness tells events.','书面'),C('relate.s4','口语','Many new parents can relate to the exhaustion described in the article.','许多新手父母都能体会文章中所说的疲惫。','relate to someone/experience','口语：理解并对某人的经历感同身受。','parents recognize same feeling.','口语')],M('The witness related the storm by refusing to describe anything she had seen or heard.','The witness related what she had seen during the storm.','拒绝讲述任何经历不是 relate 在“叙述”义上的用法。','meaning'),[Q(1,'The analyst related the cost increase to higher shipping fees. The analyst…','connected the two things','described the fees as a family member','rejoiced at the increase','Relate A to B means show a connection between them.','meaning'),Q(2,'A safety rule that relates to visitors…','concerns or applies to visitors','is a story visitors told','is unrelated to them','Relate to can mean concern or apply to a subject.','context'),Q(3,'The witness related what she had seen. She…','told the events she observed','refused to remember anything','connected a cable to the courthouse','This sense means narrate or recount.','meaning'),Q(4,'A reader can relate to a character when the reader…','understands or identifies with the character’s experience','files a rejection against the character','rehearses the character’s lines only','Relate to a person or experience means feel able to understand it.','context')]);
P('related','From relate + past-participle suffix -ed, ultimately from Latin referre “carry back”; related means connected with someone or something.',C('related.s1','通用','Please send the invoices and any related documents with your application.','提交申请时，请一并发送发票及任何相关文件。','related documents/issues; related to + noun','形容词：与某人或某事存在联系。','documents concern application.','通用'),M('The related documents had no connection whatsoever to the application or its subject.','The related documents concerned the application and its subject.','毫无关联的文件不能称为 related。','meaning'),[Q(1,'Related documents are documents that…','are connected with the matter','have no connection with it','rejoice over it','Related means connected in some way.','meaning'),Q(1,'Which phrase is natural?','questions related to the survey','questions related the survey at','related to questions the survey of','Related is commonly followed by to before the subject.','grammar'),Q(1,'An email includes reports about the same investigation. The reports are…','related to the investigation','a relapse into it','a rejoinder of it','They concern the same matter.','context'),Q(1,'Which is closest to related?','connected','unconnected','rejected','Related describes a connection.','meaning')]);
P('relation','From Latin relatio “a bringing back, report,” from referre; relation means a connection or interaction, or a member of one’s family.',[C('relation.s1','社交','The study examined the relation between sleep and memory.','这项研究考察了睡眠与记忆之间的关系。','the relation between A and B','名词：人与人或事物之间的联系、互动方式。','research compares two factors.','学术'),C('relation.s2','家庭','A distant relation of ours sent a postcard from the coast.','我们的一位远亲从海岸寄来一张明信片。','a relation of mine/ours; close relation','名词：家庭成员或亲属。','relative sends card.','家庭')],M('The study found no relation between the variables, so it proved that they were directly and strongly connected.','The study found a relation between the variables because they were directly connected.','“没有关系”与“直接且强烈相关”不能同时成立。','meaning'),[Q(1,'The relation between sleep and memory means…','the connection between them','a family member visiting both','a delay in a rehearsal','Relation sense 1 names a connection or interaction.','meaning'),Q(2,'A distant relation is…','a member of one’s extended family','a scientific connection between two variables','a piece of merchandise','Relation can be a noun meaning family member.','meaning'),Q(1,'Which phrase is natural?','the relation between the two events','the relation among the two events between','relation the events to between','The common pattern is relation between A and B.','grammar'),Q(1,'Which sentence uses relation to mean a relative?','A relation from Canada visited us.','The relation between the prices fell.','She related the prices to her cousin.','A relation can be a family member.','context')]);
P('relational','From relation + -al, ultimately from Latin relatio; relational describes something concerning connections between people, ideas, or data.',C('relational.s1','学术','The team stored customer records in a relational database with linked tables.','团队将客户记录存储在一个由关联表组成的关系型数据库中。','relational database/model','形容词：涉及事物间关系而非孤立属性的；计算机中指以相互关联的表组织数据。','tables connect through shared fields.','计算机'),M('A relational database stores every item separately with no links or relationships between tables.','A relational database organizes data in tables that are linked by shared fields.','没有表间关系与 relational 的核心含义相反。','meaning'),[Q(1,'A relational database organizes information using…','tables linked through relationships','a single unconnected list only','a family relation’s postcard','Relational in computing refers to linked data tables.','meaning'),Q(1,'Which phrase is natural?','a relational model of the data','a relationing model relationally','relational to model the data at','Relational is an adjective modifying model or database.','grammar'),Q(1,'A study compares how family members affect one another. It studies…','relational patterns','a reagent','a reindeer','The adjective concerns connections among people.','context'),Q(1,'The suffix -al in relational forms…','an adjective meaning “related to”','a past-tense verb','a plural noun','Relational is the adjective formed from relation.','word-formation')]);
P('relationship','From relation + -ship, with relation from Latin relatio; relationship means a connection between people or things, including a romantic or sexual connection.',[C('relationship.s1','社交','A good working relationship with the supplier helped resolve the delay.','与供应商保持良好的工作关系有助于解决延误。','a relationship with/between + people','名词：人与人或群体之间的联系和相处方式。','cooperation with supplier.','商务'),C('relationship.s2','情感','They decided to keep their relationship private until they were ready to tell their families.','他们决定暂时对恋爱关系保密，等准备好后再告诉家人。','a romantic/long-distance relationship','名词：两个人之间的恋爱或性关系。','couple keeps romance private.','情感')],M('They described their romantic relationship as a complete absence of any personal connection between them.','They described their romantic relationship as a close personal connection between them.','恋爱关系意味着两人存在个人联系，并非完全没有联系。','meaning'),[Q(1,'A working relationship with a supplier is…','a professional connection and way of dealing with each other','a disease relapse','a relative’s birth certificate','The first sense concerns a connection between people or groups.','meaning'),Q(2,'A romantic relationship is…','a romantic or sexual connection between two people','a contract to rejoin a work group','a relation between sleep and memory','This sense names a couple’s personal connection.','context'),Q(1,'Which phrase is natural?','a relationship with her manager','a relationship at her manager to','relationship her manager by of','Relationship commonly takes with or between to identify people.','grammar'),Q(1,'A couple dates and shares a romantic bond. They are in…','a relationship','a rejection','a rein','The word can name a romantic connection.','meaning')]);
P('relative','From Latin relativus “having reference or relation”; relative means considered in comparison with something else, connected with a noun in grammar, or a member of one’s family.',[C('relative.s1','通用','The cost is low relative to the savings it produces.','与它带来的节省相比，这项成本较低。','relative to + comparison','形容词：相对于另一事物衡量，而非绝对地衡量。','cost compared with savings.','通用'),C('relative.s2','语言','In “the book that I borrowed,” the word “that” introduces a relative clause.','在“我借的那本书”中，that 引导一个关系从句。','relative clause/pronoun','语法：指向前述名词或引导关系从句的。','that links clause to noun.','语言'),C('relative.s3','家庭','A relative will pick up the children while we are away.','我们不在时，一位亲戚会来接孩子。','a close/distant relative','名词：家庭成员或亲属。','family member helps.','家庭')],M('The fee is relative to the comparison means that it is measured with no reference to anything else.','The fee is relative to income, so it is compared with income rather than treated as absolute.','relative to 表示通过参照对象来比较，不是完全不参照。','meaning'),[Q(1,'A cost that is low relative to income is…','low when compared with income','low in every possible situation without comparison','a relative who has income','Relative sense 1 uses a comparison rather than an absolute measure.','meaning'),Q(2,'A relative clause is a grammatical clause that…','is connected to a noun or pronoun','names a family member','compares two prices only','In grammar, relative describes a clause linked to a noun.','context'),Q(3,'Which sentence uses relative as a family noun?','My relative is visiting this weekend.','The price is relative to demand.','A relative clause follows the noun.','A relative can mean a member of one’s family.','meaning'),Q(1,'Which construction is correct?','relative to the local average','relative with the local average to','relatively of the local average','The comparison is commonly introduced by to.','grammar')]);
P('relatively','From relative + -ly; relative comes from Latin relativus “having reference”; relatively means in comparison with others or fairly, but not absolutely.',[C('relatively.s1','通用','The trail is relatively flat compared with the steep route across the ridge.','与穿越山脊的陡峭路线相比，这条小径相对平坦。','relatively + adjective/adverb; relatively to (less common)','副词：与同类对象相比而言。','one trail compared to steeper route.','通用'),C('relatively.s2','通用','The equipment is relatively inexpensive, though it is not the cheapest model.','这台设备价格相当便宜，不过并非最便宜的型号。','relatively easy/large/expensive','副词：相当、颇为，表示达到一定程度但并非极端。','price is fairly low, not lowest.','通用')],M('The model is relatively inexpensive, meaning it is unquestionably the most expensive model available.','The model is relatively inexpensive, meaning it costs fairly little compared with others.','“相当便宜”与“最贵”在这里意思相反。','meaning'),[Q(1,'The trail is relatively flat compared with the ridge route. It is…','flatter in comparison with that route','perfectly flat in all conditions','a relative of the ridge','Relatively can mark a comparison with similar things.','meaning'),Q(2,'“Relatively inexpensive” usually means…','fairly inexpensive, though not necessarily the cheapest','the most expensive without exception','free of any price','This use means to a fair degree, not absolutely.','context'),Q(1,'Which placement is natural?','a relatively small room','a room relativelyly small','a relative small room','Relatively is an adverb modifying the adjective small.','grammar'),Q(1,'The word relatively signals that a statement is…','comparative or limited in degree','an absolute guarantee','a family connection','Both senses allow comparison or qualification of degree.','meaning')]);
P('relatives','From relative + plural -s; relative comes from Latin relativus; relatives are members of one’s family other than one’s immediate household.',C('relatives.s1','家庭','We invited our relatives from three provinces to the reunion.','我们邀请了来自三个省份的亲戚参加团聚。','close/distant relatives; relatives from + place','复数名词：父母、子女、配偶以外的家庭成员。','extended family attends gathering.','家庭'),M('They invited their relatives, meaning only strangers with no family connection to them.','They invited their relatives, including cousins and aunts.','relatives 指有家庭关系的人，不是毫无亲缘的陌生人。','meaning'),[Q(1,'Relatives are…','members of one’s family','people who work as reindeer','unconnected strangers','The noun refers to family members.','meaning'),Q(1,'Which phrase is natural?','distant relatives','distant relations relativesly','relative the distant at','Distant relatives are family members with a less close connection.','collocation'),Q(1,'An aunt, cousin, and grandparent visit for a holiday. They are the host’s…','relatives','rejections','rehearsals','These visitors are members of the extended family.','context'),Q(1,'Which is the singular form of relatives?','relative','relativity','relational','Relative is the singular noun; relatives is its plural.','grammar')]);
P('relativity','From relative + -ity, from Latin relativus; relativity names Einstein’s theory of space, time, and gravity, or the condition of depending on context or viewpoint.',[C('relativity.s1','科学','Einstein’s theory of relativity changed how physicists describe space and time.','爱因斯坦的相对论改变了物理学家描述时空的方式。','the theory of relativity','名词：爱因斯坦关于时空与引力的物理理论。','physicists discuss space-time theory.','物理'),C('relativity.s2','通用','The relativity of prices became clear when we compared them across different markets.','把价格放在不同市场中比较后，其相对性就显而易见了。','the relativity of + judgment/value','名词：判断或价值依赖观察角度或具体情境的性质。','comparison changes perception.','通用')],M('The theory of relativity claims that all measurements of space and time are identical for every observer.','The theory of relativity explains how measurements of space and time can depend on an observer’s motion.','该理论恰恰涉及观察者状态对测量的影响，不声称所有测量完全相同。','meaning'),[Q(1,'The theory of relativity is associated with…','Einstein’s account of space, time, and gravity','the study of family relatives','the practice of reheating food','Sense 1 is a physics theory.','meaning'),Q(2,'The relativity of a judgment means it…','depends on viewpoint or context','is always absolute and context-free','belongs to one’s family','The second sense concerns dependence on perspective or circumstances.','context'),Q(1,'Which phrase is natural?','the relativity of value','the relative of value theory','relativity to value of family','Relativity can be followed by of to name a quality that varies by context.','grammar'),Q(1,'Which field studies the theory of relativity?','physics','paleontology','pharmacology','The first sense is a major physical theory.','meaning')]);
P('relax','From Latin relaxare “loosen, open”; relax means rest and become calmer, make muscles or a grip less tight, or make a rule less strict.',[C('relax.s1','生活','After the exam, I listened to quiet music to relax.','考试结束后，我听轻音乐放松。','relax after work; relax by doing + activity','动词：休息并让身心平静下来。','music helps calm down.','生活'),C('relax.s2','医学','The therapist showed him how to relax the muscles in his shoulders.','治疗师教他如何放松肩部肌肉。','relax muscles/grip','动词：使肌肉或紧握的部位松弛。','shoulder muscles loosen.','医学'),C('relax.s3','正式','The city agreed to relax the parking restrictions on Sundays.','市政府同意在周日放宽停车限制。','relax a rule/restriction/standard','动词：使规则或管控不那么严格。','restriction becomes less strict.','政策')],M('The city relaxed the parking restrictions by making them stricter and adding more penalties.','The city relaxed the parking restrictions by removing some limits.','增加限制和惩罚是收紧规则，不是放宽。','meaning'),[Q(1,'After listening to music to relax, someone should feel…','calmer and less tense','more tightly gripped','subject to stricter parking rules','Sense 1 means rest and become calm.','meaning'),Q(2,'A therapist asks a patient to relax the shoulders. The patient should…','loosen the shoulder muscles','tighten them as hard as possible','rejoin the waiting room','Relax sense 2 means make muscles less tense.','context'),Q(3,'To relax a restriction is to…','make it less strict','increase its severity','reject it as a family member','This sense concerns easing a rule or control.','meaning'),Q(1,'Which phrase is natural?','relax the safety rules slightly','relax to the safety rules by','relaxing the rules with stricter','Relax can take a rule as a direct object.','grammar')]);
P('relaxation','From relax + -ation, from Latin relaxare “loosen”; relaxation is rest that eases tension or the act of making a rule less strict.',[C('relaxation.s1','通用','Gardening provides relaxation after a demanding week at the office.','忙碌的一周后，园艺活动能让人放松。','relaxation after/from + stress; relaxation activity','名词：消除紧张与忧虑的休息或娱乐。','gardening helps unwind.','生活'),C('relaxation.s2','通用','The relaxation of the import rules allowed small farms to sell abroad.','进口规定放宽后，小型农场得以向海外销售。','relaxation of rules/controls','名词：使规则、限制或管控不那么严格。','less strict regulation.','政策')],M('The relaxation of the rules meant that every restriction became tighter and harder to satisfy.','The relaxation of the rules meant that some restrictions became less strict.','放宽规则意味着限制有所减轻，而不是加严。','meaning'),[Q(1,'Gardening provides relaxation because it…','offers rest and eases tension','adds stricter legal controls','rehearses a work meeting','Relaxation sense 1 is rest or an activity that removes tension.','meaning'),Q(2,'The relaxation of import rules means…','the rules have become less strict','the rules have become more restrictive','the rules have been translated','The second sense is a loosening of a regulation.','context'),Q(1,'Which phrase is natural?','a relaxation of the restrictions','a relaxation to restrictions into','relaxation the restrictions at of','The noun commonly takes of before the rules or restrictions.','grammar'),Q(1,'Which verb forms the noun relaxation?','relax','reiterate','relegate','Relaxation is formed from relax with -ation.','word-formation')]);
P('relaxed','From relax + past-participle suffix -ed; relax comes from Latin relaxare “loosen.” Relaxed describes a calm state or an informal, unhurried style.',[C('relaxed.s1','心理','He felt relaxed once the interview was over and the decision had been made.','面试结束、结果已定后，他感到放松了。','feel/look relaxed','形容词：平静而不焦虑或紧张。','worry ends.','心理'),C('relaxed.s2','通用','The café has a relaxed atmosphere, with no dress code or fixed seating.','这家咖啡馆氛围轻松随意，没有着装规定，也没有固定座位。','relaxed atmosphere/style/rules','形容词：轻松随意、不拘谨或不匆忙的。','informal café.','生活')],M('He was relaxed because he remained extremely nervous and tense throughout the interview.','He was relaxed because the interview was over and he no longer felt tense.','持续极度紧张与 relaxed 的“平静”义相反。','meaning'),[Q(1,'A relaxed interviewee is…','calm and not nervous','under pressure and panicking','a relative of the interviewer','Sense 1 describes a calm emotional state.','meaning'),Q(2,'A relaxed dress code is…','informal and not strict','more restrictive than a uniform','a rehearsal schedule','Sense 2 describes an easy, informal arrangement.','context'),Q(1,'Which phrase is natural?','a relaxed atmosphere','an atmosphere relaxedly','a relaxation atmosphere of','Relaxed is an adjective that can modify atmosphere.','grammar'),Q(1,'The adjective relaxed is formed from…','relax + -ed','rely + -ance','release + -ive','The past-participle form of relax also functions as an adjective.','word-formation')]);
P('relay','From French relayer “change horses,” from re- + layer “leave”; relay can mean a staged team race, an electrical switch or signal repeater, or pass information onward.',[C('relay.s1','体育','Each swimmer in the relay completed one length before tagging the next teammate.','接力赛中，每位游泳选手游完一段后交接给下一位队友。','a relay race; run/swim a relay','名词：队员分段完成的接力比赛。','team members take turns.','体育'),C('relay.s2','通讯','A hilltop station relays the emergency signal to nearby towns.','山顶站把紧急信号转发给附近城镇。','relay a signal/broadcast','名词：经另一站转发的广播或信号。','station passes signal on.','通讯'),C('relay.s3','电学','A small relay switches the pump on when the water level rises.','水位升高时，一个小继电器会启动水泵。','an electric relay; relay switch','名词：控制电路通断的电气装置。','device switches circuit.','电学'),C('relay.s4','通用','Please relay the revised meeting time to everyone on the team.','请把修改后的会议时间转告给团队所有人。','relay a message/information to + person','动词：把消息从一人传达给另一人。','message is passed along.','通用')],M('Please relay the revised time by keeping it secret and making sure nobody else receives the message.','Please relay the revised time by passing the information on to the team.','不让他人收到消息与传达消息相反。','meaning'),[Q(1,'In a swimming relay, teammates…','each complete one part of the race','all swim the entire course at once','send a signal through a circuit','Relay sense 1 is a race completed in stages by team members.','meaning'),Q(2,'A relay station in broadcasting…','passes a signal onward','runs the final lap of a race','rejects the broadcast permanently','A relay can repeat or pass along a signal.','context'),Q(3,'An electrical relay is used to…','switch a circuit','describe a family relationship','rejuvenate a swimmer','The device opens or closes an electrical circuit.','meaning'),Q(4,'To relay a meeting change to coworkers is to…','pass the information on to them','delete the change from the calendar','join their meeting again without telling them','The verb means convey a message to others.','context')]);
P('release','From Old French relaisser “relinquish,” from Latin relaxare “loosen”; release means set free, make public, let something out, or an act/product of releasing.',[C('release.s1','法律','The court ordered the release of the witness after her testimony.','证词结束后，法院下令释放这名证人。','release a person/animal from + place','动词：让人或动物获得自由、离开拘押。','witness is freed.','法律'),C('release.s2','传媒','The studio will release the documentary in cinemas next month.','制片公司下个月将在影院发行这部纪录片。','release a film/product/statement','动词：使电影、新闻或产品向公众开放。','film becomes available publicly.','传媒'),C('release.s3','科学','The sensor releases a small amount of gas when it gets too hot.','传感器过热时会释放少量气体。','release gas/chemical/pressure','动词：使气体、化学物质或被压住的东西逸出。','gas escapes from device.','科学'),C('release.s4','传媒','The band announced the release of its new album for Friday.','乐队宣布新专辑将于周五发行。','a release of + product; a new release','名词：释放这一行为，或新近公开发行的作品。','album made available.','传媒')],M('The studio released the film by keeping it locked away so that no member of the public could see it.','The studio released the film by making it available to the public.','将影片封存、不让公众观看不是发行。','meaning'),[Q(1,'A court orders a witness’s release. The witness is…','set free from custody','published as a film','reheated in a laboratory','Sense 1 means let a person go free.','meaning'),Q(2,'A studio releases a film when it…','makes the film available to the public','withdraws it before anyone can see it','sends the actors to a relay race','Release sense 2 concerns public distribution.','context'),Q(3,'A valve releases gas when it…','lets gas escape','stores the gas more tightly','makes gas into a relative','Sense 3 is to let a substance out.','meaning'),Q(4,'A new album release is…','the album’s public launch or availability','the band’s private rehearsal','the act of rejecting the album','Release as a noun can name a product made public.','context')]);
P('relegate','From Latin relegare “send away,” from re- + legare “send”; relegate means put a person, team, or issue in a lower rank or less important position.',C('relegate.s1','通用','The editor relegated the brief announcement to the final page of the report.','编辑把这则简短公告放到了报告的最后一页。','relegate someone/something to + lower position','动词：将某人或某事降到较低等级或次要地位。','announcement moved to less prominent place.','通用'),M('The promotion relegated her to a lower position with fewer duties and less authority.','The promotion elevated her to a higher position with more responsibility.','relegate 是降级或置于次要位置，不是晋升。','distinction'),[Q(1,'To relegate a subject to a footnote is to…','give it a less important position','make it the report’s main topic','rejoice over it publicly','Relegate means place something lower or less prominently.','meaning'),Q(1,'Which construction is correct?','relegate the issue to a minor role','relegate the issue at minor role','relegate to the issue a minor role','The usual pattern is relegate something to a position.','grammar'),Q(1,'A team finishes last and moves to a lower league. It is…','relegated','rejuvenated','released','The team has been assigned a lower rank.','context'),Q(1,'Which word is closest to relegate?','demote','promote','reinforce','Relegate often means demote or make secondary.','meaning')]);
P('relentless','From relent + -less; relent comes through Old French from Latin lentus “slow, yielding.” Relentless means continuing without pause or acting without pity.',[C('relentless.s1','通用','The relentless rain continued through the night and flooded the lower road.','大雨整夜不停，淹没了较低处的道路。','relentless rain/pressure/effort','形容词：持续不断、不减弱的。','rain does not stop.','通用'),C('relentless.s2','书面','The prosecutor was relentless in questioning the witness about the missing records.','检察官不留情面地追问证人关于失踪记录的问题。','relentless pursuit/questioning','形容词：严厉而不留情的。','questioning is severe and persistent.','法律')],M('The relentless storm stopped after ten minutes and never returned, yet it was described as continuous for weeks.','The relentless storm continued for days without a break.','短暂停止且不再返回与持续不断的描述矛盾。','meaning'),[Q(1,'Relentless rain is rain that…','continues without stopping','falls once and never returns','is a family relation','Sense 1 means unceasing or persistent.','meaning'),Q(2,'A relentless prosecutor is…','severe and unwilling to ease the questioning','kindly and quick to abandon every question','a weather report','Sense 2 can describe harsh, pitiless persistence.','context'),Q(1,'Which phrase is natural?','relentless pressure','relentless at the pressure by','relent pressureless','Relentless can modify pressure, effort, rain, and similar nouns.','collocation'),Q(1,'What does -less contribute to relentless?','without or lacking','again','the act of','The adjective describes someone or something that does not relent.','word-formation')]);
P('relevance','From relevant + -ance, ultimately from Latin relevare “raise”; relevance is the degree to which something connects with a topic or is useful to a discussion.',[C('relevance.s1','通用','The relevance of the survey depends on whether it includes rural households.','这项调查是否相关，取决于它是否涵盖农村家庭。','relevance of A to B','名词：一事物与另一事物的关联程度。','survey population affects link.','通用'),C('relevance.s2','通用','The judge questioned the relevance of the photograph to the case.','法官质疑这张照片与案件是否切题。','relevance to the case/topic','名词：对正在讨论的问题是否切题、有用。','photo may not aid case.','法律')],M('The judge called the photograph relevant to the case while ruling that it had no connection or usefulness to it.','The judge questioned the photograph’s relevance because it had no connection with the case.','若完全无关联且无用，就不应称为 relevant。','meaning'),[Q(1,'The relevance of a survey to a rural study concerns…','how closely its evidence connects with that study','the survey’s rehearsal schedule','its distance from a relay station','Relevance sense 1 concerns the connection between things.','meaning'),Q(2,'Evidence with relevance to a case is…','useful or connected to what is being discussed','unrelated to every issue in the case','automatically rejected','The second sense is being pertinent to a discussion.','context'),Q(1,'Which phrase is natural?','the relevance of the evidence to the case','relevance the case from evidence at','relevance with case of evidence','The common pattern is relevance of X to Y.','grammar'),Q(1,'Which noun is closest to relevance?','pertinence','irrelevance','reimbursement','Relevance is the quality of being pertinent or connected.','meaning')]);
P('relevant','From French relever “raise,” from Latin relevare; relevant means connected with the subject being discussed or important and useful in the present situation.',[C('relevant.s1','通用','Please include only evidence relevant to the question before the committee.','请只提交与委员会当前问题相关的证据。','relevant to + topic/question','形容词：与正在讨论的主题密切相关。','evidence matches issue.','通用'),C('relevant.s2','社会','Local bus access is especially relevant to older residents who cannot drive.','对无法开车的老年居民来说，当地公交尤其重要。','relevant to + person/situation','形容词：在当前情形下有现实意义或重要性。','bus access matters now.','社会')],M('The committee excluded the report as relevant even though it had no connection to the question.','The committee excluded the report as irrelevant because it had no connection to the question.','没有关联的报告应称 irrelevant，而非 relevant。','distinction'),[Q(1,'Evidence relevant to a question is…','connected with that question','unrelated to it','a relative of the committee','Relevant sense 1 means pertinent to the subject.','meaning'),Q(2,'Bus access is relevant to older residents when it…','matters to their present situation','has no effect on their lives','is a rehearsal of another issue','Sense 2 means important or useful in a situation.','context'),Q(1,'Which phrase is correct?','relevant to the discussion','relevant with the discussion','relevant at discussing','Relevant is normally followed by to.','grammar'),Q(1,'The opposite of relevant is…','irrelevant','reliable','relaxed','Irrelevant means not connected with the subject.','meaning')]);
P('reliability','From reliable + -ity; reliable is related to rely, ultimately from Latin religare “bind fast.” Reliability is the quality of being dependable or working consistently.',C('reliability.s1','通用','The mechanic tested the reliability of the backup generator before winter.','入冬前，维修工测试了备用发电机的可靠性。','reliability of a person/machine/test','名词：人、机器或测试值得依赖、稳定工作的程度。','test checks steady operation.','工程'),M('The generator’s reliability was proven by its frequent unexplained failures and inability to start.','The generator’s reliability was supported by its consistent starts and failure-free operation.','频繁故障表明不可靠，而不是 reliability。','meaning'),[Q(1,'A generator’s reliability refers to…','how dependably it works','how often it fails unexpectedly','how many relatives it has','Reliability is the quality of being dependable.','meaning'),Q(1,'Which phrase is natural?','the reliability of the test','the reliable of the test','reliability to the test by','Reliability is a noun commonly followed by of.','grammar'),Q(1,'A test gives consistent results each time. It has high…','reliability','reluctance','relevance only to rain','Consistency supports reliability.','context'),Q(1,'Which adjective is the base of reliability?','reliable','relief','relation','Reliability is formed from reliable with -ity.','word-formation')]);
P('reliable','From rely + -able; rely comes from Old French relier “bind,” from Latin religare; reliable means trustworthy or able to work steadily without breaking down.',[C('reliable.s1','通用','Mina is reliable: she arrives when promised and keeps confidential information private.','米娜值得信赖：她按约定到达，并对保密信息守口如瓶。','a reliable person/source','形容词：可以信任其行为或判断的。','person keeps commitments.','通用'),C('reliable.s2','工业','This reliable pump has run for five years without an unexpected shutdown.','这台可靠的水泵五年来没有意外停机。','reliable equipment/service','形容词：稳定耐用、不易出故障的。','machine works steadily.','工业')],M('The reliable pump stopped unexpectedly every day and could not complete a single cycle.','The reliable pump ran steadily for years without an unexpected shutdown.','每天意外停机说明设备不可靠。','meaning'),[Q(1,'A reliable coworker is someone who…','can be trusted to keep promises','regularly forgets assigned tasks','is a distant relation only','Sense 1 describes a trustworthy person.','meaning'),Q(2,'A reliable pump is one that…','works steadily without frequent breakdowns','stops unexpectedly every day','relaxes a rule','Sense 2 describes dependable equipment.','context'),Q(1,'Which phrase is natural?','a reliable source of information','a reliably source of information','a source reliablely of information','Reliable is an adjective modifying source.','grammar'),Q(1,'Which quality is opposite to reliable?','dependable','untrustworthy','relational','A reliable person or device can be depended on.','meaning')]);
P('reliance','From rely + -ance, ultimately from Latin religare “bind”; reliance is dependence on someone or something, or trust that they will do what is needed.',[C('reliance.s1','通用','The island’s reliance on imported fuel makes transport disruptions costly.','这个岛对进口燃料的依赖使交通中断代价高昂。','reliance on + person/resource','名词：需要某人或某物提供支持的状态。','island needs fuel imports.','通用'),C('reliance.s2','通用','Her reliance on the guide’s judgment was justified by his long experience.','她信赖向导的判断，这份信任因他的丰富经验而有依据。','reliance on someone’s judgment','名词：相信某人会做到所需之事的信任。','guide is trusted.','通用')],M('The island’s reliance on imported fuel meant it could operate normally with no fuel at all.','The island’s reliance on imported fuel meant a shortage could disrupt transport.','依赖燃料意味着缺少燃料会造成影响，不是无需燃料也能运转。','meaning'),[Q(1,'Reliance on imported fuel means…','depending on imported fuel for support','being completely independent of fuel','rejoicing at the fuel price','Sense 1 is dependence on a resource.','meaning'),Q(2,'Her reliance on the guide’s judgment shows…','trust that he will make sound decisions','a refusal to listen to him','a family relation to the guide','Sense 2 concerns trust in another person.','context'),Q(1,'Which phrase is correct?','reliance on the evidence','reliance of the evidence to','reliance at evidence','Reliance is commonly followed by on.','grammar'),Q(1,'Which verb forms reliance?','rely','release','relegate','Reliance is the noun related to rely.','word-formation')]);
P('reliant','From rely + -ant, ultimately from Latin religare “bind”; reliant means needing a particular person, system, or resource in order to function or survive.',C('reliant.s1','通用','The small clinic is reliant on volunteers to keep its evening service open.','这家小诊所依靠志愿者维持晚间服务。','reliant on + person/resource','形容词：依赖某人或某种资源才能运转或生存。','clinic needs volunteer help.','通用'),M('The clinic is reliant on volunteers, so it can remain fully staffed even when no volunteers come.','The clinic is reliant on volunteers, so its service may shrink when they are unavailable.','依赖志愿者意味着缺少志愿者会受影响。','meaning'),[Q(1,'A clinic reliant on volunteers…','depends on them to provide service','operates without any help from them','rejects every volunteer','Reliant on means dependent on.','meaning'),Q(1,'Which phrase is natural?','reliant on public transport','reliant to public transport','reliant public transport with','The adjective is followed by on before the support source.','grammar'),Q(1,'A farm needs one river for irrigation and cannot function without it. The farm is…','reliant on the river','a rejoinder to the river','relatively a river','The farm depends on the river as a resource.','context'),Q(1,'Which word is closest to reliant?','dependent','independent','release','Reliant means depending on something.','meaning')]);
P('relic','From Latin reliquiae “remains,” from relinquere “leave behind”; a relic is an object from the past, especially a valued sacred object, or a surviving old custom.',[C('relic.s1','宗教','The museum displayed a small relic believed to have belonged to the medieval saint.','博物馆展出了一件小圣物，据说曾属于那位中世纪圣徒。','a relic of/from + historical person','名词：留存至今的旧物，尤指与圣人有关而受珍视的物品。','historic object is preserved.','宗教'),C('relic.s2','社会','The paper form is a relic of an earlier system that most offices have abandoned.','这种纸质表格是旧制度的遗风，大多数办公室早已弃用。','a relic of + past era/system','引申为从过去留存下来、如今显得过时的事物。','old form remains after system changes.','社会')],M('The paper form was a relic of the new system because it had just been invented and was used everywhere today.','The paper form was a relic of the old system because it had survived after offices adopted a new one.','刚发明且普遍使用的事物不是旧时代的遗留物。','meaning'),[Q(1,'A museum relic is…','an object surviving from the past','a new product released today','a person who relays a signal','Relic sense 1 is a valued old object.','meaning'),Q(2,'A practice called a relic of an earlier era is…','a leftover custom that now seems old-fashioned','a brand-new policy','a relation between two variables','The figurative sense describes something surviving from the past.','context'),Q(1,'Which phrase is natural?','a relic of the medieval period','a relic at the medieval period from','relic the period by medieval','Relic is commonly followed by of to identify its historical source.','grammar'),Q(1,'A centuries-old object kept in a shrine may be a…','relic','reliever','relay','A relic can be a valued sacred object.','meaning')]);
P('relict','From Latin relictus “left behind,” past participle of relinquere; a relict is a surviving fragment of an earlier population, custom, or landscape.',C('relict.s1','科学','The isolated plant population is a relict from a colder period when the species ranged farther south.','这个孤立的植物种群是寒冷时期遗留下来的残存种群，当时该物种分布得更靠南。','a relict population/species/landform','名词：早期种群、习俗或地貌留存下来的残余部分。','population survives after range shrinks.','生态'),M('The relict population had just arrived from a thriving new range and had no connection to any earlier population.','The relict population survived from an earlier period after the species’ range contracted.','relict 指从更早时期存留下来的残余，不是新近扩张来的群体。','meaning'),[Q(1,'A relict population is…','a surviving remnant of an earlier population','a newly invented species with no history','a team in a relay race','Relict names a surviving fragment from an earlier time.','meaning'),Q(1,'Which phrase is natural in ecology?','a relict species','a relictly species','relict of the species at','Relict can directly modify species or population.','collocation'),Q(1,'An old landform left after a coastline changes may be a…','relict','rejoinder','reimbursement','A relict may be a landscape feature surviving from an earlier period.','context'),Q(1,'The root idea in relict is something…','left behind','published to the public','made more reliable','The word comes from a Latin form meaning “left behind.”','word-formation')]);
P('relief','From relieve, via Old French relever “raise”; relief is a lessening of pain or worry, a feeling or cause of comfort, or aid for people in need.',[C('relief.s1','健康','The medicine brought relief from the patient’s severe back pain.','这种药缓解了患者严重的背痛。','relief from pain/pressure','名词：疼痛、忧虑、困难或负担的减轻。','pain lessens.','医学'),C('relief.s2','情感','There was a sigh of relief when the missing child was found safe.','失踪的孩子平安找到后，大家如释重负地松了口气。','a feeling/sigh of relief; relief to hear','名词：忧虑消失后的宽慰感，也可指令人宽慰的人或事。','danger is over.','情感'),C('relief.s3','社会','Emergency relief supplied clean water to families displaced by the flood.','紧急救援为洪水迫使离家的家庭提供了清洁饮水。','emergency/disaster relief','名词：给予贫困、生病或遇险者的援助。','aid reaches displaced families.','社会')],M('The pain relief made the patient’s pain much more severe and harder to bear.','The pain relief made the patient’s pain less severe.','relief 指减轻痛苦，而不是使痛苦加重。','meaning'),[Q(1,'Medicine brought relief from pain. The pain…','became less severe','became more intense','was sent to a relay station','Relief sense 1 is a lessening of pain.','meaning'),Q(2,'A sigh of relief usually follows…','the end of a worry or danger','the start of a new emergency','a family meeting','Relief can be the feeling when a worry disappears.','context'),Q(3,'Disaster relief provides…','help to people in danger or need','a stricter rule for importers','a film’s public release','Relief sense 3 is aid for people affected by hardship.','meaning'),Q(1,'Which phrase is natural?','relief from stress','relief at stress from to','relieving of stress by relief','Relief is often followed by from to name what is reduced.','grammar')]);
P('relieve','From Latin relevare “raise, lighten”; relieve means make pain or difficulty less severe, ease someone’s anxiety, take over a duty, or free someone from a job or burden.',[C('relieve.s1','医学','The cold pack helped relieve the swelling around his ankle.','冷敷有助于减轻他脚踝周围的肿胀。','relieve pain/pressure/symptoms','动词：减轻疼痛、忧虑或困境。','cold pack reduces swelling.','医学'),C('relieve.s2','情感','It relieved her to learn that everyone had arrived safely.','得知所有人都已安全抵达，她感到宽慰。','it relieves someone to + clause','动词：使某人不再焦虑或担心。','good news eases worry.','情感'),C('relieve.s3','职场','A second nurse arrived at midnight to relieve the nurse on duty.','午夜时，另一名护士前来接替值班护士。','relieve someone on duty; relieve a guard','动词：接替某人的工作或值班。','new nurse takes over shift.','职场'),C('relieve.s4','正式','The company relieved the manager of her duties during the investigation.','调查期间，公司解除了这位经理的职务。','relieve someone of duties/responsibility','正式：解除某人的职务或使其摆脱负担。','manager no longer has role.','正式')],M('The cold pack relieved his swelling by making it larger and more painful.','The cold pack relieved his swelling by reducing it.','缓解意味着减轻症状，而不是使其恶化。','meaning'),[Q(1,'A medicine relieves pain when it…','makes the pain less severe','makes the pain more intense','takes over a nurse’s shift','Sense 1 means reduce pain or difficulty.','meaning'),Q(2,'“It relieved her to hear the news” means the news…','made her less anxious','made her more worried','dismissed her from work','Sense 2 describes easing someone’s worry.','context'),Q(3,'A nurse arrives to relieve the nurse on duty. The new nurse…','takes over that nurse’s shift','makes the nurse’s pain worse','releases a film','Sense 3 means replace someone at a job or duty.','meaning'),Q(4,'To relieve a manager of her duties is to…','remove those responsibilities from her','give her more duties','make her feel calm about a storm only','Sense 4 means free someone from a responsibility or post.','context')]);
P('relieved','From relieve + -ed; relieve is based on Latin relevare “lighten.” Relieved means glad that a worry or danger has passed, or describes pain or pressure that has been reduced.',[C('relieved.s1','通用','I was relieved to hear that the hikers had reached the cabin safely.','听说徒步者已安全抵达木屋，我松了一口气。','be relieved to hear/know; feel relieved','形容词：因担忧或危险消失而感到宽慰。','news removes worry.','通用'),C('relieved.s2','通用','The relieved pressure let the swollen hose return to its normal shape.','压力减轻后，鼓胀的软管恢复了正常形状。','relieved pain/pressure/tension','形容词：疼痛、压力或紧张得到缓解的。','pressure has lessened.','工程')],M('She was relieved to hear the hikers were safe, so she became more worried than ever.','She was relieved to hear the hikers were safe, so her worry eased.','安全消息带来宽慰，不会让她因此更加担心。','meaning'),[Q(1,'A person relieved by good news feels…','glad because worry has eased','more anxious than before','ready to relegate a team','Sense 1 is an emotional response to danger or worry passing.','meaning'),Q(2,'Relieved pressure on a hose means the pressure…','has been reduced','has increased sharply','has been released as a film','Sense 2 describes a lowered physical pressure.','context'),Q(1,'Which phrase is natural?','relieved to hear the news','relieved hearing of to the news','relief to hear the newsed','Relieved commonly takes to + verb for the cause of comfort.','grammar'),Q(1,'Which word is the base verb for relieved?','relieve','rely','relegate','Relieved is the -ed form of relieve.','word-formation')]);
P('reliever','From relieve + -er, based on Latin relevare “lighten”; a reliever is a person or thing that eases pain or pressure or takes over another person’s task.',C('reliever.s1','通用','The night-shift reliever arrived early so the day nurse could go home.','夜班替班人员提前到岗，这样白班护士就能回家。','a reliever for + person/task; pain reliever','名词：减轻疼痛或压力的人/物，也可指接替他人工作的人。','worker takes over duty.','职场'),M('The reliever left the shift uncovered and refused to take over any duties from the exhausted nurse.','The reliever took over the exhausted nurse’s duties so she could leave.','拒绝接班并留下空缺不符合 reliever 的含义。','meaning'),[Q(1,'A night-shift reliever is someone who…','takes over another worker’s duty','adds a new shift to the tired nurse','rehearses a film release','A reliever can take over another person’s task.','meaning'),Q(1,'A pain reliever is a medicine that…','reduces pain','makes pain worse','relegates the patient','The word also names something that eases pain.','context'),Q(1,'Which phrase is natural?','a reliever for the day nurse','a reliever to the day nurse of','reliever the day nurse with','A reliever can be identified by the task or person relieved.','grammar'),Q(1,'The suffix -er in reliever commonly refers to…','a person or thing that performs an action','a past event only','a comparison with another thing','Reliever is formed from relieve + -er.','word-formation')]);
P('religion','From Latin religio “reverence, religious obligation,” of uncertain deeper origin; religion is belief in a god or gods and related worship, a particular faith, or figurative devotion to an activity.',[C('religion.s1','宗教','The museum’s new gallery explores religion in ancient river societies.','博物馆的新展厅探讨古代河流文明中的宗教。','religion and worship; practice a religion','名词：对神或诸神的信仰，以及相关的崇拜和义务。','gallery examines belief and worship.','宗教'),C('religion.s2','宗教','Her family practices a religion that observes a weekly day of rest.','她的家人信奉一种每周设有休息日的宗教。','a particular religion; convert to a religion','名词：一套特定的信仰与崇拜体系。','family follows one faith.','宗教'),C('religion.s3','口语','For the dedicated baker, weighing every ingredient is almost a religion.','对这位投入的面包师来说，称量每种原料几乎成了一种执念。','make something a religion (figurative)','口语比喻：把某项活动当作极其重要的追求。','baker treats routine with devotion.','口语')],M('The gallery called the practice a religion even though it involved no belief, worship, or particular faith.','The gallery described the tradition as a religion because it involved shared beliefs and worship.','若无信仰或崇拜，把它定义为字面宗教就缺乏依据。','meaning'),[Q(1,'Religion in the first sense includes…','belief in a god or gods and related worship','a weekly meeting with no beliefs of any kind','a machine that switches a circuit','Sense 1 includes belief and associated duties or worship.','meaning'),Q(2,'A particular religion is…','a specific system of faith and worship','a family member only','a science test’s reliability','Sense 2 refers to one organized faith.','context'),Q(3,'“Baking is almost a religion to her” is figurative and means…','she treats baking as an extremely important pursuit','she worships a loaf as a god in a literal report','she has stopped baking entirely','The idiom-like figurative use signals intense devotion to an activity.','meaning'),Q(1,'Which phrase is natural?','practice a religion','practice in a religion to','religion practice of at','Practice can take religion as its direct object.','collocation')]);
P('religious','From religion + -ous, ultimately from Latin religio; religious means connected with a religion or having strong belief and following its practices.',[C('religious.s1','宗教','The archive preserves religious texts from several communities in the region.','档案馆保存着该地区多个群体的宗教文本。','religious text/ceremony/tradition','形容词：与某一宗教或信仰有关。','texts concern faith.','宗教'),C('religious.s2','宗教','Her religious grandparents attend services every week and follow the faith closely.','她虔诚的祖父母每周参加礼拜，并严格遵循信仰。','a religious person; deeply religious','形容词：虔诚地相信上帝并遵守宗教规范的。','people observe their faith.','宗教')],M('The religious ceremony had nothing to do with any faith, worship, or sacred tradition.','The religious ceremony formed part of the community’s worship and faith tradition.','完全不涉及信仰或崇拜的仪式不能称为宗教仪式。','meaning'),[Q(1,'A religious text is one that…','is connected with a faith or worship','describes a family member only','is always about a relay race','Sense 1 concerns connection with religion.','meaning'),Q(2,'A deeply religious person is likely to…','hold strong beliefs and follow the faith’s practices','reject every form of belief','write only a technical manual','Sense 2 describes personal devotion.','context'),Q(1,'Which phrase is natural?','a religious ceremony','a religionly ceremony','a religious of ceremony','Religious is an adjective modifying ceremony.','grammar'),Q(1,'Which noun is religious formed from?','religion','relief','relic','The adjective is formed from religion with -ous.','word-formation')]);
P('religiously','From religious + -ly; religious comes from religion, from Latin religio; religiously means in a way that follows religious duty or with extremely regular, devoted consistency.',C('religiously.s1','通用','She checks the greenhouse temperature religiously every morning, even on holidays.','她每天早晨都一丝不苟地检查温室温度，节假日也不例外。','follow/check/read something religiously','副词：严格按宗教义务行事；引申为极其规律、虔诚般地坚持。','habit is followed without fail.','通用'),M('He followed the safety checklist religiously, skipping it whenever he felt tired.','He followed the safety checklist religiously every day without skipping steps.','经常跳过清单与一丝不苟地坚持相矛盾。','meaning'),[Q(1,'She checks the greenhouse religiously. She does it…','with very regular, devoted consistency','only once and never again','as a formal act of worship necessarily','The common figurative sense means doing something very regularly.','meaning'),Q(1,'Which sentence uses religiously naturally?','He reads the safety instructions religiously before each repair.','He religiously readed the instructions at tomorrow.','He checks them religious every day.','Religiously is an adverb modifying the action reads.','grammar'),Q(1,'A runner follows the same training routine every day without fail. The runner follows it…','religiously','relatively','reliant','The adverb emphasizes faithful regularity.','context'),Q(1,'Religiously is formed by adding -ly to…','religious','religion','relic','The adverb comes from the adjective religious.','word-formation')]);
P('relinquish','From Latin relinquere “leave behind,” from re- + linquere “leave”; relinquish means formally give up power, control, a right, or a claim.',C('relinquish.s1','法律','The owner agreed to relinquish her claim to the disputed land.','所有者同意放弃对这片争议土地的权利主张。','relinquish control/power/a claim','动词：正式放弃权力、控制权或权利主张。','owner gives up legal claim.','法律'),M('The owner relinquished her claim by continuing to insist that the land belonged exclusively to her.','The owner relinquished her claim by signing a document giving up her rights.','继续坚持独占权不是放弃权利主张。','meaning'),[Q(1,'To relinquish a claim is to…','formally give it up','strengthen it with new evidence','rejoin the owner’s family','Relinquish means give up a right or claim.','meaning'),Q(1,'Which phrase is natural?','relinquish control of the company','relinquish the company to control of','relinquishing at company from control','Relinquish takes the right or power being surrendered as its object.','grammar'),Q(1,'A leader steps down and gives up authority. The leader…','relinquishes power','rehearses power','relieves power from a film','Relinquish applies to power and control.','context'),Q(1,'Which word is closest to relinquish?','surrender','retain','reinforce','To relinquish is to surrender something held.','meaning')]);
P('relish','From Old French relaisser “leave over,” later influenced by re- + licere “be pleasing”; relish means enjoy greatly, eagerness for something, or a strongly flavoured sauce.',[C('relish.s1','通用','She relished the chance to explain how the restoration had saved the old theater.','她很享受解释这次修复如何拯救了老剧院的机会。','relish an opportunity/challenge','动词：从某事中获得很大乐趣。','speaker enjoys describing work.','通用'),C('relish.s2','情感','He spoke with relish about the close finish of the race.','他兴致勃勃地讲起那场势均力敌的比赛。','with relish; take relish in + activity','名词：强烈的兴致或享受。','speaker shows eager enjoyment.','情感'),C('relish.s3','饮食','The café serves a sharp tomato relish beside the grilled vegetables.','这家咖啡馆在烤蔬菜旁配上一份味道浓郁的番茄酱。','tomato/onion relish; relish with + food','名词：佐以清淡食物的辛香酱料，也指浓烈风味。','sauce accompanies vegetables.','饮食')],M('She relished the opportunity by dreading it and hoping that she would never have to take part.','She relished the opportunity and eagerly accepted it.','害怕并希望避开机会，与 enjoy it greatly 相反。','meaning'),[Q(1,'She relished the chance to present her work. She…','enjoyed the opportunity greatly','avoided it because she hated the task','asked for a reindeer','Relish as a verb means enjoy something greatly.','meaning'),Q(2,'He told the story with relish. He spoke with…','eagerness and enjoyment','fear and unwillingness','a legal claim','The noun sense is keen enjoyment or enthusiasm.','context'),Q(3,'A tomato relish served with vegetables is…','a strongly flavoured sauce','a dessert spoon used for measuring','a relationship between plants','Relish can name a savoury condiment.','meaning'),Q(1,'Which construction is correct?','relish the challenge','relish in the challenge it','relish to the challenge','Relish as a verb usually takes a direct object.','grammar')]);
P('reload','From re- “again” + load, from Old English hladan “load”; reload means put a new load into a machine, weapon, or device again.',C('reload.s1','工具','The photographer had to reload the camera before taking more pictures.','摄影师在继续拍照前必须给相机重新装胶卷。','reload a camera/printer/weapon','动词：再次向机器或武器装入所需材料。','camera needs new film.','工具'),M('The photographer reloaded the camera by removing its film and leaving it empty before taking more pictures.','The photographer reloaded the camera by inserting a fresh roll of film.','取出胶卷使相机变空，不是重新装入。','meaning'),[Q(1,'To reload a camera is to…','put more film or another load into it','delete every photograph from a screen','move the camera to a new office','Reload means load something again.','meaning'),Q(1,'Which phrase is natural?','reload the printer with paper','reload paper out of the printer','reload to paper at the printer','The device is reloaded with the material it uses.','grammar'),Q(1,'After its ammunition runs out, a tool user reloads the device by…','putting in another supply','throwing it away permanently','relegating it to a museum','Reload describes loading the device again.','context'),Q(1,'What does re- mean in reload?','again','under','without','The prefix marks a repeated loading action.','word-formation')]);
P('relocate','From re- + locate, based on Latin locus “place”; relocate means move to a new place to live or work, or move an organization or activity there.',C('relocate.s1','商务','The design firm will relocate to a larger office near the train station.','这家设计公司将迁到火车站附近一间更大的办公室。','relocate to + place; relocate a business','动词：搬到新的居住或工作地点。','firm moves its workplace.','商务'),M('The firm relocated to a new office by remaining in the same building and never moving.','The firm relocated by moving its staff and equipment to a new office.','留在原地没有搬迁，不是 relocate。','meaning'),[Q(1,'A firm relocates when it…','moves to a new place','renews an old argument','remains permanently in the same office','Relocate means move to a different place.','meaning'),Q(1,'Which construction is natural?','relocate to a larger office','relocate at a larger office to','relocate the larger office at to','The move destination is introduced by to.','grammar'),Q(1,'A family moves to another city for work. The family…','relocates','relishes','reiterates','They have moved to a new place to live.','context'),Q(1,'The word relocate contains re- and a word related to…','place or position','family relation','medical relief','Locate concerns position; relocate is to place again elsewhere.','word-formation')]);
P('reluctance','From reluctant + -ance, from Latin reluctari “struggle against”; reluctance is unwillingness to do something or hesitation caused by doubt or fear.',[C('reluctance.s1','通用','Her reluctance to sign the agreement came from concerns about the delivery dates.','她不愿签署协议，是因为担心交货日期。','reluctance to do something','名词：不愿做别人要求之事。','she is unwilling to sign.','通用'),C('reluctance.s2','通用','After a moment of reluctance, he stepped onto the dark stage.','犹豫了一会儿后，他走上了昏暗的舞台。','reluctance about/at + action','名词：因疑虑或害怕而产生的迟疑。','fear delays action.','通用')],M('Her reluctance to sign showed that she was eager to sign immediately and had no concerns.','Her reluctance to sign showed that she was unwilling because of her concerns.','急于签署且毫无顾虑不是不情愿。','meaning'),[Q(1,'Reluctance to sign an agreement means…','unwillingness to sign it','eagerness to sign it at once','a relative’s signature','Sense 1 is unwillingness to do something.','meaning'),Q(2,'A moment of reluctance before entering a dark room is…','hesitation caused by doubt or fear','a quick and confident entry','a formal rejection from a court','Sense 2 is hesitation.','context'),Q(1,'Which phrase is correct?','reluctance to speak','reluctance for speaking to','reluctantly to speak reluctance','Reluctance is commonly followed by to plus a verb.','grammar'),Q(1,'Which adjective is the base of reluctance?','reluctant','reliable','relational','Reluctance is the noun form of reluctant.','word-formation')]);
P('reluctant','From Latin reluctari “struggle against,” with adjective suffix -ant; reluctant means unwilling and therefore slow to agree or act.',[C('reluctant.s1','通用','The reluctant witness finally agreed to answer the lawyer’s questions.','这位不情愿的证人最终同意回答律师的问题。','reluctant to do something','形容词：不愿意做某事，因而迟迟不答应。','witness hesitates to answer.','法律'),C('reluctant.s2','通用','She gave a reluctant nod before handing over the keys.','她迟疑地点了点头，然后交出了钥匙。','a reluctant agreement/smile/nod','形容词：表现出不情愿、不热心或犹豫。','gesture shows hesitation.','通用')],M('The reluctant witness eagerly volunteered to answer every question before being asked.','The reluctant witness hesitated and agreed only after repeated requests.','主动急切地回答与 reluctant 的迟疑不愿相反。','meaning'),[Q(1,'A reluctant witness is…','unwilling and slow to agree','eager to volunteer immediately','a courtroom relay runner','Reluctant describes unwillingness.','meaning'),Q(2,'A reluctant nod suggests…','hesitation or lack of enthusiasm','complete excitement','a refusal to hear anything at all','Sense 2 describes an action that shows unwillingness.','context'),Q(1,'Which phrase is grammatical?','reluctant to answer','reluctant for answer','reluctantly to an answer','Reluctant is followed by to + base verb.','grammar'),Q(1,'The opposite of reluctant is…','willing','hesitant','unenthusiastic','Reluctant means unwilling, so willing is its opposite.','meaning')]);
P('reluctantly','From reluctant + -ly; reluctant is from Latin reluctari “struggle against.” Reluctantly means in a way that shows one does not really want to act.',C('reluctantly.s1','通用','He reluctantly lent his car after checking that the trip was insured.','确认旅程有保险后，他才勉强借出了汽车。','reluctantly agree/accept/do something','副词：经过犹豫后不情愿地做某事。','agreement follows hesitation.','通用'),M('She reluctantly accepted the invitation and was delighted to do so without any hesitation or doubts.','She reluctantly accepted the invitation, although she would have preferred to stay home.','没有犹豫且欣然接受与 reluctantly 相反。','meaning'),[Q(1,'He reluctantly lent his car. He did so…','although he did not really want to','with eager excitement and no hesitation','because a relay race required it','Reluctantly means unwillingly or after hesitation.','meaning'),Q(1,'Which sentence uses reluctantly correctly?','She reluctantly agreed after asking for more time.','She gave a reluctantly answerly.','Reluctantly, she agree the tomorrow.','Reluctantly is an adverb modifying agreed.','grammar'),Q(1,'A child finally shares a toy only after repeated requests. The child shares it…','reluctantly','reliably','relationally','The child is unwilling and slow to agree.','context'),Q(1,'Reluctantly is formed from…','reluctant + -ly','reluctance + -er','relief + -ment','The -ly ending forms the adverb from reluctant.','word-formation')]);
P('rely','From Old French relier “bind,” from Latin religare “bind fast”; rely means need someone or something for support, or trust that someone will do what is expected.',[C('rely.s1','通用','The village relies on the spring for most of its drinking water.','这个村庄的大部分饮用水依靠这处泉水。','rely on/upon + resource','动词：需要某人或某物以维持生活或取得成功。','village depends on spring.','通用'),C('rely.s2','通用','You can rely on Noor to return the keys before the office closes.','你可以相信努尔会在办公室关门前归还钥匙。','rely on someone to do something','动词：相信某人会按预期采取行动。','trusted person will return keys.','通用')],M('The village relies on the spring for water, so it can thrive even when the spring is completely dry.','The village relies on the spring for water, so a dry spring would create a shortage.','依赖水源意味着水源干涸时会受到影响。','meaning'),[Q(1,'A village that relies on a spring…','depends on it for water','does not need any water source','has a relay race on the spring','Rely sense 1 means depend on something needed.','meaning'),Q(2,'You can rely on Noor to return the keys if…','you trust Noor to do what is expected','you expect Noor to lose them','Noor is your relative only','Sense 2 is trust in someone’s action.','context'),Q(1,'Which construction is correct?','rely on the evidence','rely the evidence at','rely to the evidence on','Rely normally requires on before its object.','grammar'),Q(1,'Which word is closest to rely on?','depend on','reject','release','Rely on means depend on or trust.','meaning')]);
P('rely on','From rely + the particle on; rely comes through Old French relier from Latin religare “bind fast.” Rely on means depend on a person or thing to provide support or do what is expected.',C('rely on.s1','通用','The rescue crew relied on the radio operator to coordinate the boats.','救援队依靠无线电操作员协调各艘船只。','rely on someone/something to do something','短语动词：依靠某人或某物满足需要、提供支持或完成预期任务。','crew depends on operator.','通用'),M('The rescue crew relied on the radio operator, but the operator was never asked to provide any help or information.','The rescue crew relied on the radio operator to pass on their locations and instructions.','依靠某人意味着需要其帮助或信号；完全不需要其提供任何东西与 rely on 不符。','meaning'),[Q(1,'The crew relied on the operator to coordinate the boats. The operator…','was trusted to provide needed help','was irrelevant to the rescue','was a relict population','Rely on means depend on someone to do what is needed.','meaning'),Q(1,'Which phrase is correct?','rely on a map for directions','rely a map for directions on','rely to a map of directions','The phrasal verb is rely on.','grammar'),Q(1,'A patient depends on a nurse to bring medicine at the right time. The patient…','relies on the nurse','relies the nurse','rejoices the nurse','Dependence on a person for support is rely on.','context'),Q(1,'What does on do in rely on?','introduces the person or thing depended upon','marks a past tense','means “without”','The particle is required to connect rely with its object.','grammar')]);
P('remain','From Old French remanoir, from Latin remanere “stay behind,” from re- + manere “stay”; remain means continue in a state, be left over, stay in a place, or surviving remains.',[C('remain.s1','通用','Despite the changes, the original purpose of the project remained clear.','尽管发生了变化，项目最初的目标仍然明确。','remain + adjective/noun','动词：继续处于同一状态。','purpose stays clear.','通用'),C('remain.s2','通用','Only two seats remained after the concert tickets were sold.','音乐会门票售出后只剩下两个座位。','remain after + event; remain to be done','动词：其他部分消失、用完或离开后还留下。','two seats are left.','通用'),C('remain.s3','书面','The hikers remained in the cabin until the storm passed.','暴风雨过去前，徒步者一直留在木屋里。','remain in/at + place','动词：停留在某地而不离开。','people stay indoors.','书面'),C('remain.s4','历史','Archaeologists studied the remains of a stone wall beside the road.','考古学家研究了路旁石墙的遗迹。','human/ancient remains','复数名词：遗址、遗骸或某物遗留下来的部分。','old wall parts survive.','历史')],M('Only two seats remained after the concert, meaning every seat had been taken and none were left.','Only two seats remained after the concert, meaning two seats were still available.','remain 在此义为仍剩下；“没有剩余”与“还剩两座”矛盾。','meaning'),[Q(1,'The purpose remained clear means it…','continued to be clear','was left behind as a physical object','was released to the public','Sense 1 is continuing in the same state.','meaning'),Q(2,'Only two seats remained means…','two seats were still left','two seats had vanished before sale','the room stayed in one place','Sense 2 is what is left after others are used.','context'),Q(3,'The hikers remained in the cabin. They…','stayed there and did not leave','were assigned to a lower rank','repeated the cabin’s name','Sense 3 means stay in a place.','meaning'),Q(4,'Archaeologists studied ancient remains. They studied…','surviving parts of an old structure or body','the building’s future plans','a group of living relatives','Remains can mean what survives from the past.','context')]);
P('remainder','From remain + -der, an altered form of remainder; remain comes from Latin remanere “stay behind.” Remainder is the part left after the rest is used or the amount left in a calculation.',[C('remainder.s1','通用','She packed the remainder of the bread for tomorrow’s lunch.','她把剩下的面包打包，留作明天的午餐。','the remainder of + amount/group','名词：其他部分用掉或处理后剩下的部分。','bread is left over.','通用'),C('remainder.s2','教育','When 23 is divided by 5, the remainder is 3.','23 除以 5，余数是 3。','the remainder after division','名词：除法或减法后剩下的数值。','math calculation leaves three.','数学')],M('After 23 is divided by 5, the remainder is 0 because the result is 4 with 3 left over.','After 23 is divided by 5, the remainder is 3.','4余3的计算中，余数不可能同时是0。','meaning'),[Q(1,'The remainder of the bread is…','the bread left after some was eaten or used','the first loaf before anyone ate','a family member of the baker','Sense 1 is a leftover part.','meaning'),Q(2,'In 23 divided by 5, the remainder is…','3','4','5','Five goes into 23 four times, leaving 3.','context'),Q(1,'Which phrase is natural?','the remainder of the group','the remainder at the group from','remainder the group of it','Remainder commonly takes of before the whole from which a part is left.','grammar'),Q(1,'Which mathematical operation can produce a remainder?','division','rejoicing','relocation','A remainder is the amount left over after division.','meaning')]);
P('remaining','From remain + -ing; remain comes from Latin remanere “stay behind.” Remaining describes what is still left after some part has been taken or dealt with.',C('remaining.s1','通用','Please use the remaining paint to touch up the door frame.','请用剩下的油漆修补门框。','the remaining + noun; remaining time/items','形容词：处理或取走一部分后仍留下的。','paint still left.','通用'),M('She used the remaining paint after every drop had already been used up.','She used the remaining paint that was still in the can.','若油漆已全部用完，就没有 remaining paint。','meaning'),[Q(1,'The remaining paint is paint that…','is still left in the can','has all been used','was never part of the can','Remaining means still left after some has been used.','meaning'),Q(1,'Which phrase is natural?','the remaining three pages','the remainly three pages','three remaining of page','Remaining can modify a noun directly.','grammar'),Q(1,'A team has completed seven of ten tasks. The tasks not yet done are the…','remaining tasks','rejected tasks','reliant tasks','They are the ones still left to complete.','context'),Q(1,'Remaining is formed from…','remain + -ing','remainder + -ed','rely + -ment','The present-participle form remain+ing functions as an adjective here.','word-formation')]);
P('remains','From remain + plural -s; remain comes from Latin remanere “stay behind.” Remains are surviving parts of an old structure, a dead body, or something left over.',[C('remains.s1','历史','The remains of the watchtower can still be seen on the hill.','山上仍能看到瞭望塔的遗迹。','the remains of a building/site','复数名词：古建筑或结构仍然留存的部分。','tower fragments survive.','历史'),C('remains.s2','通用','The animal’s remains were examined to determine its age.','研究人员检查了这只动物的遗骸以确定它的年龄。','human/animal remains; remains of + organism','复数名词：人或动物的遗骸，也可指事物剩下的部分。','scientists inspect bones.','科学')],M('The remains of the watchtower were newly built last week and had no connection to any old structure.','The remains of the watchtower were fragments that survived from the old structure.','新建的完整建筑不是旧塔留下的遗迹。','meaning'),[Q(1,'The remains of a watchtower are…','the parts of the old structure still standing','a plan for a tower that has not been built','a relay station','Sense 1 means surviving structural fragments.','meaning'),Q(2,'Animal remains may include…','bones or other parts left after death','a living animal running in the field','a family relation','Sense 2 can mean the body or parts of a dead animal.','context'),Q(1,'Which phrase is natural?','the remains of the ancient wall','the remains at the ancient walling','remainings of wall anciently','Remains commonly takes of to identify what is left.','grammar'),Q(1,'In archaeology, remains are things that…','survive from an earlier time','will be created in the future','were never present','The word refers to what has been left behind.','meaning')]);
P('remark','From French remarquer “notice,” from re- + marquer “mark”; remark means say something as a comment, notice something, or a short statement expressing an opinion.',[C('remark.s1','通用','“The room is brighter now,” she remarked as she opened the curtains.','她拉开窗帘时说道：“现在房间亮多了。”','remark that + clause; remark on/about + topic','动词：作为评论说出自己的看法。','speaker comments on room.','通用'),C('remark.s2','书面','The inspector remarked that a crack had appeared beside the window.','检查员注意到窗边出现了一道裂缝。','remark that + observation','动词：注意到某事并提及。','inspector notices crack.','书面'),C('remark.s3','通用','His final remark made the audience reconsider the cost of the plan.','他最后的评论让听众重新考虑计划的成本。','make a remark about/on + topic','名词：表达观点的一句话或简短评论。','audience hears a comment.','通用')],M('The inspector remarked that there was no crack, while pointing directly at the large crack beside the window.','The inspector remarked that a crack had appeared beside the window.','指着明显裂缝却说没有裂缝，陈述自相矛盾。','meaning'),[Q(1,'She remarked that the room was brighter. She…','said this as a comment','noticed a room but said nothing','released a film','Remark as a verb can mean make a comment.','meaning'),Q(2,'The inspector remarked that a crack had appeared. The inspector…','noticed and mentioned it','repaired it without seeing it','made a family relation','This sense combines noticing with mentioning an observation.','context'),Q(3,'His final remark was…','a short statement expressing an opinion','a medical treatment','the remaining part of a wall','Remark as a noun is a comment.','meaning'),Q(1,'Which construction is natural?','remark on the proposal','remark the proposal on','remark at the proposal about of','Remark can be followed by on/about before a topic.','grammar')]);
P('remarkable','From remark + -able; remark is from French remarquer “notice.” Remarkable means unusually good or noteworthy, or sufficiently large or obvious to be noticed.',[C('remarkable.s1','通用','The young pianist gave a remarkable performance despite having little rehearsal time.','这位年轻钢琴家排练时间不多，却完成了一场非凡的演出。','a remarkable achievement/performance','形容词：非常出色或不同寻常，值得关注。','performance stands out.','通用'),C('remarkable.s2','科学','The instrument detected a remarkable rise in pressure within seconds.','仪器在几秒内检测到压力显著上升。','a remarkable increase/difference','形容词：大或明显到容易被注意到。','measurement changes sharply.','科学')],M('The remarkable increase was so tiny that nobody could detect or notice any change at all.','The remarkable increase was large enough for the instrument to detect immediately.','完全无法察觉的微小变化不符合显著、引人注意的含义。','meaning'),[Q(1,'A remarkable performance is…','unusually good or noteworthy','ordinary and unworthy of attention','a relay exchange','Sense 1 means outstanding or unusual.','meaning'),Q(2,'A remarkable rise in pressure is…','large or obvious enough to notice','too small for any instrument to detect','a remarkable family member','Sense 2 concerns a noticeable degree or change.','context'),Q(1,'Which phrase is natural?','a remarkable difference','a remarkably difference','remarkable of difference at','Remarkable is an adjective modifying difference.','grammar'),Q(1,'Remarkable is related to remark because it describes something…','worthy of being noticed','that cannot be mentioned','that has been reloaded','The suffix -able gives the sense “able to be remarked or noticed.”','word-formation')]);
P('remarkably','From remarkable + -ly; remarkable comes from remark, “notice.” Remarkably means to a surprising or impressive degree.',C('remarkably.s1','通用','The old footbridge remained remarkably sturdy after years of storms.','这座旧人行桥历经多年风暴后仍然异常坚固。','remarkably + adjective/adverb','副词：达到令人惊讶或印象深刻的程度。','bridge is unusually strong.','通用'),M('The bridge was remarkably sturdy, meaning it was so weak that it collapsed under its own weight.','The bridge was remarkably sturdy and withstood storms that damaged nearby structures.','坚固耐用与弱到自重下坍塌正相反。','meaning'),[Q(1,'Remarkably sturdy means…','strong to a surprising degree','weak and easily broken','related to a family member','Remarkably intensifies an adjective to an unusual degree.','meaning'),Q(1,'Which sentence uses remarkably correctly?','The patient recovered remarkably quickly.','The patient made a remarkably recovery.','Remarkably, the patient recover yesterday quicklyly.','Remarkably is an adverb modifying quickly.','grammar'),Q(1,'A small town attracts an unusually large number of visitors. It is…','remarkably popular','reluctantly popular','reliability popular','The adverb signals a surprising degree of popularity.','context'),Q(1,'Remarkably is built from the adjective…','remarkable','remark','remainder','The -ly ending forms an adverb from remarkable.','word-formation')]);
P('remedial','From remedy + -al, from Latin remedium “cure”; remedial means intended to correct a fault, address harm, or help someone reach a basic level of learning.',C('remedial.s1','教育','Students who need extra reading support attend a remedial class after school.','需要额外阅读辅导的学生放学后参加补习课。','remedial class/education/support','形容词：旨在弥补学习差距或达到基本水平。','class fills learning gap.','教育'),M('The remedial class was designed to widen students’ reading gaps and prevent them from learning basic skills.','The remedial class was designed to address students’ reading gaps and teach basic skills.','补习课旨在弥补差距，不是扩大差距。','meaning'),[Q(1,'A remedial reading class is intended to…','help students correct a learning gap','make students forget basic reading','rejoin a theater group','Remedial education helps learners reach a needed level.','meaning'),Q(1,'Which phrase is natural?','remedial support for struggling readers','remedially support for readers','remedial of support to readers','Remedial is an adjective modifying support.','grammar'),Q(1,'A student receives extra instruction to address weak math skills. The instruction is…','remedial','relentless','relic','It is designed to correct a learning difficulty.','context'),Q(1,'Remedial is related to which noun?','remedy','remain','reliance','A remedial measure is intended as a remedy.','word-formation')]);
P('remediation','From remediate + -ation; remediate is formed from remedy, from Latin remedium “cure.” Remediation is work that removes damage or corrects a learning difficulty.',C('remediation.s1','环境','The remediation of the polluted soil began after the factory was closed.','工厂关闭后，受污染土壤的修复工作开始了。','environmental/site remediation','名词：清除污染或修复环境损害的工作；也指补救学习困难。','cleanup treats contaminated soil.','环境'),M('The soil remediation plan spread more pollution into the ground instead of cleaning or treating it.','The soil remediation plan removed the contaminants and tested the cleaned ground.','把污染物扩散开不是 remediation。','meaning'),[Q(1,'Soil remediation is work that…','removes pollution or repairs environmental damage','adds more pollutants to the soil','measures the soil’s color only','Remediation corrects environmental harm.','meaning'),Q(1,'Which phrase is natural?','remediation of contaminated land','remediation at contaminate land of','remedialization the land pollutedly','Remediation is commonly followed by of to name the harm treated.','grammar'),Q(1,'A school provides targeted lessons to fill a student’s skill gap. This is…','learning remediation','a relict landscape','a release of a product','Remediation can address a learning difficulty.','context'),Q(1,'Which verb is the base of remediation?','remediate','remark','rely','Remediation is formed from remediate + -ation.','word-formation')]);
P('remedy','From Old French remede, from Latin remedium “cure, remedy”; remedy is a medical treatment, a solution or legal means of correcting a wrong, or the act of correcting a problem.',[C('remedy.s1','医学','The pharmacist suggested a simple remedy for the mild throat irritation.','药剂师为轻微的喉咙刺激提出了一种简单疗法。','a remedy for + illness/problem','名词：治疗疾病的药物或方法。','treatment eases throat.','医学'),C('remedy.s2','通用','A clearer timetable may be a remedy for the repeated scheduling confusion.','更清晰的时间表或许能解决反复出现的排期混乱。','a remedy for a problem','名词：处理或解决问题的方法。','new schedule fixes confusion.','通用'),C('remedy.s3','法律','The judge ordered a financial remedy for the residents harmed by the breach.','法官判令为因违约受损的居民提供经济补救。','a legal remedy for + wrong','名词：法律允许用来纠正侵害的救济方式。','court orders compensation.','法律'),C('remedy.s4','正式','The agency changed its inspection process to remedy the safety failures.','该机构改变了检查流程，以纠正安全漏洞。','remedy a fault/problem/shortcoming','动词：纠正、改善不良情况。','process is corrected.','正式')],M('The new inspection policy remedied the safety failures by repeating the same faulty checks and changing nothing.','The new inspection policy remedied the safety failures by correcting the faulty checks.','不改任何缺陷无法纠正安全问题。','meaning'),[Q(1,'A remedy for a sore throat is…','a treatment intended to ease it','a cause of more pain','a report about a relict species','Sense 1 is a cure or treatment.','meaning'),Q(2,'A remedy for scheduling confusion might be…','a clearer timetable','a more confusing schedule','a reliever who never arrives','Sense 2 is a solution to a problem.','context'),Q(3,'A legal remedy is…','a means the law provides to correct a wrong','a medical prescription only','a family member’s opinion','Sense 3 names legal relief for an injury or wrong.','meaning'),Q(4,'To remedy a safety fault is to…','correct or improve it','make it worse','relegate it without repair','The verb remedy means put a problem right.','context')]);
P('remember','From Old French remembrer, from Latin rememorari “recall to mind”; remember means keep or bring a fact to mind, deliberately not forget something, or send greetings through someone.',[C('remember.s1','通用','I remember the first day we opened the community library.','我记得社区图书馆开门的第一天。','remember + person/event/that-clause','动词：脑海中留有过去的事实或经历。','speaker recalls past event.','通用'),C('remember.s2','通用','Remember to lock the side gate before you leave tonight.','今晚离开前记得锁上侧门。','remember to do something','动词：有意识地记住要做某事，确保不忘记。','instruction concerns future action.','通用'),C('remember.s3','社交','Please remember me to your parents when you see them this weekend.','你这周末见到父母时，请代我向他们问好。','remember someone to + person','社交用法：请某人代为向另一人问候。','greetings passed along.','社交')],M('She remembered to lock the gate, but left it open all night and said she had secured it.','She remembered to lock the gate and checked that it was shut before leaving.','若侧门整夜敞开，就没有完成“记得锁门”这一动作。','meaning'),[Q(1,'“I remember the opening day” means…','I can recall that past event','I must not forget a future task','I send greetings to the opening day','Sense 1 concerns facts or events held in memory.','meaning'),Q(2,'“Remember to lock the gate” means…','do not forget to perform that future action','recall that you locked it last year only','tell the gate to send a greeting','Remember to do something is a reminder about a task.','context'),Q(3,'“Remember me to your parents” means…','give my greetings to them','do not forget who your parents are','recall a story about a parent','This social expression asks someone to pass on greetings.','meaning'),Q(1,'Which phrase is natural for a task not yet done?','remember to call the clinic','remember calling the clinic yesterday only','remembered to call tomorrow yesterday','Remember to do something refers to a future action.','grammar')]);
})();
